// Offline IBAN shape and checksum observations.
// Typo catch only — not a bank lookup and not a claim that an account exists.

const LENGTHS = {
  AD: 24, AE: 23, AL: 28, AT: 20, AZ: 28, BA: 20, BE: 16,
  BG: 22, BH: 22, BR: 29, BY: 28, CH: 21, CR: 22, CY: 28,
  CZ: 24, DE: 22, DK: 18, DO: 28, EE: 20, EG: 29, ES: 24,
  FI: 18, FO: 18, FR: 27, GB: 22, GE: 22, GI: 23, GL: 18,
  GR: 27, GT: 28, HR: 21, HU: 28, IE: 22, IL: 23, IQ: 23,
  IS: 26, IT: 27, JO: 30, KW: 30, KZ: 20, LB: 28, LC: 32,
  LI: 21, LT: 20, LU: 20, LV: 21, LY: 25, MC: 27, MD: 24,
  ME: 22, MK: 19, MR: 27, MT: 31, MU: 30, NL: 18, NO: 15,
  PK: 24, PL: 28, PS: 29, PT: 25, QA: 29, RO: 24, RS: 22,
  SA: 24, SE: 24, SI: 19, SK: 24, SM: 27, TN: 24, TR: 26,
  UA: 29, VA: 22, VG: 24, XK: 20,
};

function finding(rule, message, fix, path) {
  return { rule, message, fix, path };
}

export function normalizeIban(value) {
  if (typeof value !== "string") return null;
  const compact = value.toUpperCase().replace(/[^A-Z0-9]/g, "");
  return compact || null;
}

function classify(compact) {
  if (compact.length < 15 || compact.length > 34) return "unknown";
  const country = compact.slice(0, 2);
  const check = compact.slice(2, 4);
  const bban = compact.slice(4);
  if (!/^[A-Z]{2}$/.test(country) || !/^\d{2}$/.test(check) || !/^[A-Z0-9]+$/.test(bban)) {
    return "unknown";
  }
  const expected = LENGTHS[country];
  if (expected === undefined) return "checksum";
  if (compact.length !== expected) return "bad-format";
  return "checksum";
}

function mod97Ok(compact) {
  const rearranged = compact.slice(4) + compact.slice(0, 4);
  let numeric = "";
  for (const char of rearranged) {
    numeric += parseInt(char, 36).toString(10);
  }
  let remainder = 0;
  for (const digit of numeric) {
    remainder = (remainder * 10 + Number(digit)) % 97;
  }
  return remainder === 1;
}

export function looksLikeCompleteIban(value) {
  const compact = normalizeIban(value);
  if (compact === null) return false;
  // "checksum" is a known-length (or unknown-country) shape ready for the
  // mod-97 check; "bad-format" is a known country whose length is wrong.
  // Both are IBAN-shaped enough for the cross-field checks that gate on this
  // (BIC country match, remittance-missing, payment-means-needs-IBAN) --
  // only "unknown" (no country-shaped prefix at all, e.g. an internal
  // account id) should read as "there is no IBAN here". This used to check
  // for a classify() result of "format", which classify() never returns, so
  // every wrong-length IBAN silently read as "not an IBAN" and skipped those
  // checks instead of surfacing them alongside the length finding.
  const kind = classify(compact);
  return kind === "checksum" || kind === "bad-format";
}

function checkExplicit(value, path) {
  if (typeof value !== "string" || !value.trim()) {
    return [finding(
      "INV-024",
      "Payment IBAN is empty or not text.",
      "Provide the IBAN as text, or omit payment.iban.",
      path,
    )];
  }
  const compact = normalizeIban(value);
  if (compact === null) {
    return [finding(
      "INV-024",
      "Payment IBAN is empty or not text.",
      "Provide the IBAN as text, or omit payment.iban.",
      path,
    )];
  }
  const kind = classify(compact);
  if (kind === "unknown") {
    return [finding(
      "INV-024",
      "Payment IBAN is not a country-prefixed account number.",
      "Use a two-letter country prefix, two check digits, and the national account number, or omit payment.iban.",
      path,
    )];
  }
  if (kind === "bad-format") {
    const country = compact.slice(0, 2);
    return [finding(
      "INV-024",
      `Payment IBAN does not match the published ${country} length.`,
      `Correct the ${country} IBAN length and characters, or omit payment.iban for an internal account id.`,
      path,
    )];
  }
  if (kind === "checksum" && !mod97Ok(compact)) {
    const country = compact.slice(0, 2);
    return [finding(
      "INV-025",
      `Payment IBAN fails the published ${country} checksum.`,
      `Correct the ${country} IBAN digits. This is a checksum typo check, not a bank lookup.`,
      path,
    )];
  }
  return [];
}

export function inspectPaymentIban(invoice) {
  const payment = invoice.payment;
  if (!payment || typeof payment !== "object" || Array.isArray(payment)) return [];
  const iban = payment.iban;
  if (iban === undefined || iban === null || iban === "") return [];
  return checkExplicit(iban, "/payment/iban");
}

means.mjs.text:
// Offline payment-means (BT-81 / UNCL 4461) observations.
// Mirrors src/einvoice_preflight/means.py. Findings never repeat the
// typed code or the account. This is a typo and consistency check, not
// a Peppol profile determination.

import { looksLikeCompleteIban } from "./iban.mjs";

const KNOWN_MEANS = new Set([
  "1", "10", "20", "30", "31", "42", "48", "49", "50", "57", "58", "59", "97",
]);
const ACCOUNT_REQUIRED = new Set(["30", "31", "42", "49", "58", "59"]);
const CASH_LIKE = new Set(["10", "20", "48"]);

function finding(rule, message, fix, path) {
  return { rule, message, fix, path };
}

export function normalizeMeans(value) {
  if (typeof value === "boolean") return null;
  if (typeof value === "number" && Number.isInteger(value) && value >= 0) {
    return String(value);
  }
  if (typeof value !== "string") return null;
  const compact = value.trim();
  return compact || null;
}

export function looksLikeKnownMeans(value) {
  return KNOWN_MEANS.has(normalizeMeans(value));
}

export function inspectPaymentMeans(invoice) {
  const payment = invoice && typeof invoice === "object" && !Array.isArray(invoice)
    ? invoice.payment
    : undefined;
  if (!payment || typeof payment !== "object" || Array.isArray(payment) || !("means" in payment)) {
    return [];
  }
  const raw = payment.means;
  if (raw === null || raw === "") {
    return [finding(
      "INV-044",
      "Payment means code is empty or not a documented UNCL 4461 code.",
      "Use a published payment means code such as 30, 58, or 10, or omit payment.means.",
      "/payment/means",
    )];
  }
  const compact = normalizeMeans(raw);
  if (compact === null || !KNOWN_MEANS.has(compact)) {
    return [finding(
      "INV-044",
      "Payment means code is empty or not a documented UNCL 4461 code.",
      "Use a published payment means code such as 30, 58, or 10, or omit payment.means.",
      "/payment/means",
    )];
  }

  const findings = [];
  const hasIban = looksLikeCompleteIban(payment.iban);
  if (ACCOUNT_REQUIRED.has(compact) && !hasIban) {
    findings.push(finding(
      "INV-045",
      "Payment means is a credit transfer, SEPA transfer, or direct debit without an IBAN.",
      "Add payment.iban for that means, switch to a cash or card means, or omit payment.means.",
      "/payment/iban",
    ));
  }
  if (CASH_LIKE.has(compact) && hasIban) {
    findings.push(finding(
      "INV-046",
      "Payment means is cash, cheque, or card but the invoice also names an IBAN.",
      "Use a credit-transfer or SEPA means with the IBAN, or omit payment.iban.",
      "/payment/means",
    ));
  }
  return findings;
}

period.mjs.text:
// Offline invoice-period (BT-73 / BT-74) observations.
// Date-shape check only — not a Peppol profile or contract match.

export function parseIsoDate(value) {
  if (typeof value !== "string" || value.length !== 10 || value[4] !== "-" || value[7] !== "-") {
    return null;
  }
  const year = Number(value.slice(0, 4));
  const month = Number(value.slice(5, 7));
  const day = Number(value.slice(8, 10));
  if (![year, month, day].every((part) => Number.isInteger(part))) return null;
  const date = new Date(Date.UTC(year, month - 1, day));
  if (
    date.getUTCFullYear() !== year ||
    date.getUTCMonth() !== month - 1 ||
    date.getUTCDate() !== day
  ) {
    return null;
  }
  return date;
}

function finding(rule, message, fix, path) {
  return { rule, message, fix, path };
}

export function inspectInvoicePeriod(invoice) {
  if (!invoice || typeof invoice !== "object" || Array.isArray(invoice) || !("period" in invoice)) {
    return [];
  }
  const period = invoice.period;
  if (period === null || period === "") return [];
  if (typeof period !== "object" || Array.isArray(period)) {
    return [finding(
      "INV-042",
      "Invoice period is not an object with start and end dates.",
      "Use period.start and period.end as YYYY-MM-DD, or omit period.",
      "/period",
    )];
  }

  const startRaw = period.start;
  const endRaw = period.end;
  const startMissing = startRaw === undefined || startRaw === null || startRaw === "";
  const endMissing = endRaw === undefined || endRaw === null || endRaw === "";
  if (startMissing && endMissing) {
    return [finding(
      "INV-042",
      "Invoice period is missing both start and end dates.",
      "Add period.start and period.end as YYYY-MM-DD, or omit period.",
      "/period",
    )];
  }

  const findings = [];
  const start = startMissing ? null : parseIsoDate(startRaw);
  const end = endMissing ? null : parseIsoDate(endRaw);
  if (startMissing) {
    findings.push(finding(
      "INV-042",
      "Invoice period is missing a start date.",
      "Add period.start as YYYY-MM-DD, or omit period.",
      "/period/start",
    ));
  } else if (start === null) {
    findings.push(finding(
      "INV-042",
      "Invoice period start is not an ISO date.",
      "Use YYYY-MM-DD, for example 2026-07-01.",
      "/period/start",
    ));
  }
  if (endMissing) {
    findings.push(finding(
      "INV-042",
      "Invoice period is missing an end date.",
      "Add period.end as YYYY-MM-DD, or omit period.",
      "/period/end",
    ));
  } else if (end === null) {
    findings.push(finding(
      "INV-042",
      "Invoice period end is not an ISO date.",
      "Use YYYY-MM-DD, for example 2026-07-31.",
      "/period/end",
    ));
  }
  if (start !== null && end !== null && end < start) {
    findings.push(finding(
      "INV-043",
      "Invoice period end is earlier than the start.",
      "Set period.end to period.start or a later date.",
      "/period/end",
    ));
  }
  return findings;
}

profile.mjs.text:
// Opt-in country profile: the German XRechnung business rules (BR-DE-*) that
// sit on top of EN 16931. The core checks answer "is this invoice
// arithmetically and structurally sound"; this answers "will a German public
// buyer's portal accept it". Rule ids are XR-nnn and name the BR-DE rule they
// mirror. Findings never repeat a typed reference or address. This is an
// offline observation, not the KoSIT validator and not a legal opinion.

const XRECHNUNG_TYPE_CODES = new Set(["326", "380", "381", "384", "389", "875", "876", "877"]);
const XRECHNUNG_SPEC = /^urn:cen\.eu:en16931:2017#(?:compliant|conformant)#urn:xeinkauf\.de:kosit:(?:xrechnung_3\.\d+|extension:xrechnung_3\.\d+)/i;

const PEPPOL_SPEC = "urn:cen.eu:en16931:2017#compliant#urn:fdc:peppol.eu:2017:poacc:billing:3.0";
const PEPPOL_PROCESS = "urn:fdc:peppol.eu:2017:poacc:billing:01:1.0";

function finding(rule, message, fix, path) {
  return { rule, message, fix, path };
}

function str(value) {
  return typeof value === "string" ? value.trim() : "";
}

function isObject(value) {
  return value && typeof value === "object" && !Array.isArray(value);
}

/** Leitweg-ID: coarse address (2-12 digits), optional fine address (up to 30
 *  letters/digits), two check digits, joined by hyphens. */
const LEITWEG_SHAPE = /^\d{2,12}(?:-[A-Za-z0-9]{1,30})?-\d{2}$/;

/** ISO 7064 MOD 97-10 over the whole id with hyphens removed and letters
 *  mapped A=10..Z=35 (the same scheme as an IBAN); a valid id leaves 1.
 *  Verified against the published samples 991-12345-73 and 09-12345-15. */
export function leitwegCheckDigitsValid(id) {
  const compact = str(id).replace(/-/g, "").toUpperCase();
  if (!compact) return false;
  let digits = "";
  for (const ch of compact) {
    digits += /\d/.test(ch) ? ch : String(ch.charCodeAt(0) - 55);
  }
  let remainder = 0;
  for (const d of digits) remainder = (remainder * 10 + Number(d)) % 97;
  return remainder === 1;
}

export function looksLikeLeitwegId(value) {
  return LEITWEG_SHAPE.test(str(value));
}

function emailOk(value) {
  const parts = value.split("@");
  return value === value.trim() && !/\s/.test(value) && parts.length === 2
    && Boolean(parts[0]) && parts[1].includes(".") && !parts[1].startsWith(".") && !parts[1].endsWith(".");
}

export const XRECHNUNG_RULES = {
  "XR-001": "Buyer reference (BR-DE-15) is missing.",
  "XR-002": "Buyer reference looks like a Leitweg-ID but its check digits are wrong.",
  "XR-003": "Payment instructions (BR-DE-1) are missing.",
  "XR-004": "Seller contact (BR-DE-2, -5, -6, -7) is incomplete.",
  "XR-005": "Seller city or postal code (BR-DE-3, -4) is missing.",
  "XR-006": "Buyer city or postal code (BR-DE-8, -9) is missing.",
  "XR-007": "Invoice type code is not one XRechnung allows (BR-DE-17).",
  "XR-008": "Specification identifier is not an XRechnung one (BR-DE-21).",
  "XR-009": "Seller has no VAT identifier or tax number (BR-DE-16).",
};

export function inspectXrechnungProfile(invoice) {
  if (!isObject(invoice)) return [];
  const findings = [];
  const supplier = isObject(invoice.supplier) ? invoice.supplier : {};
  const customer = isObject(invoice.customer) ? invoice.customer : {};

  const buyerRef = str(invoice.buyer_reference);
  if (!buyerRef) {
    findings.push(finding(
      "XR-001",
      "Buyer reference (BT-10) is missing; XRechnung requires it (BR-DE-15).",
      "Add buyer_reference: the Leitweg-ID the public body gave you, or the customer's own routing reference.",
      "/buyer_reference",
    ));
  } else if (looksLikeLeitwegId(buyerRef) && !leitwegCheckDigitsValid(buyerRef)) {
    findings.push(finding(
      "XR-002",
      "Buyer reference is shaped like a Leitweg-ID but its two check digits do not match.",
      "Copy the Leitweg-ID again from the buyer's request; a single mistyped character fails the check digits.",
      "/buyer_reference",
    ));
  }

  const payment = isObject(invoice.payment) ? invoice.payment : null;
  if (!payment || (!str(payment.means) && !str(payment.iban))) {
    findings.push(finding(
      "XR-003",
      "No payment instructions; XRechnung requires a payment means code (BR-DE-1).",
      "Add payment.means (for example 58 for SEPA credit transfer) and payment.iban.",
      "/payment",
    ));
  }

  const contact = isObject(supplier.contact) ? supplier.contact : {};
  const missing = ["name", "phone", "email"].filter((key) => !str(contact[key]));
  if (missing.length) {
    findings.push(finding(
      "XR-004",
      `Seller contact is missing its ${missing.join(", ")}.`,
      "Add supplier.contact with a name, a telephone number and an e-mail address.",
      "/supplier/contact",
    ));
  } else if (!emailOk(str(contact.email))) {
    findings.push(finding(
      "XR-004",
      "Seller contact e-mail is not shaped like an address.",
      "Use one plain address such as billing@example.com.",
      "/supplier/contact/email",
    ));
  }

  for (const [rule, role, party, code] of [["XR-005", "Seller", supplier, "3, -4"], ["XR-006", "Buyer", customer, "8, -9"]]) {
    const gaps = ["city", "postal_code"].filter((key) => !str(party[key]));
    if (gaps.length) {
      findings.push(finding(
        rule,
        `${role} ${gaps.map((g) => g.replace("_", " ")).join(" and ")} missing (BR-DE-${code}).`,
        `Add the ${role.toLowerCase()}'s city and postal code to the ${role === "Seller" ? "supplier" : "customer"} address.`,
        `/${role === "Seller" ? "supplier" : "customer"}`,
      ));
    }
  }

  const code = str(invoice.document_code);
  if (code && !XRECHNUNG_TYPE_CODES.has(code)) {
    findings.push(finding(
      "XR-007",
      `Invoice type code ${code} is not accepted by XRechnung.`,
      "Use 380 (invoice) or 381 (credit note); 326, 384, 389, 875, 876 and 877 are the other allowed codes.",
      "/document_code",
    ));
  }

  const spec = str(invoice.specification_id);
  if (spec && !XRECHNUNG_SPEC.test(spec)) {
    findings.push(finding(
      "XR-008",
      "Specification identifier (BT-24) does not name an XRechnung version.",
      "Set it to urn:cen.eu:en16931:2017#compliant#urn:xeinkauf.de:kosit:xrechnung_3.0. The older xoev-de identifier belongs to XRechnung 2.x.",
      "/specification_id",
    ));
  }

  if (!str(supplier.vat_id) && !str(supplier.tax_number)) {
    findings.push(finding(
      "XR-009",
      "Seller has neither a VAT identifier nor a tax number (BR-DE-16).",
      "Add supplier.vat_id (DE + 9 digits) or supplier.tax_number.",
      "/supplier/vat_id",
    ));
  }

  return findings;
}

export const PEPPOL_RULES = {
  "PP-001": "Business process (BT-23) is missing or is not the Peppol billing process (PEPPOL-EN16931-R001).",
  "PP-002": "Specification identifier is not Peppol BIS Billing 3.0 (PEPPOL-EN16931-R004).",
  "PP-003": "Seller electronic address (BT-34) is missing (PEPPOL-EN16931-R020).",
  "PP-004": "Buyer electronic address (BT-49) is missing (PEPPOL-EN16931-R010).",
  "PP-005": "Neither a buyer reference nor an order reference is present (PEPPOL-EN16931-R003).",
};

function hasEndpoint(party) {
  return isObject(party) && isObject(party.endpoint) && Boolean(str(party.endpoint.id));
}

/** Peppol BIS Billing 3.0 rules on top of EN 16931: what a Peppol access point
 *  rejects even when the invoice is arithmetically sound. Ids are PP-nnn and
 *  name the PEPPOL-EN16931-R rule they mirror. Offline observation only. */
export function inspectPeppolProfile(invoice) {
  if (!isObject(invoice)) return [];
  const findings = [];

  const process = str(invoice.profile_id);
  if (process !== PEPPOL_PROCESS) {
    findings.push(finding(
      "PP-001",
      process ? "Business process (BT-23) is not the Peppol billing process." : "Business process (BT-23) is missing.",
      `Set the business process to ${PEPPOL_PROCESS} (UBL cbc:ProfileID, CII BusinessProcessSpecifiedDocumentContextParameter).`,
      "/profile_id",
    ));
  }

  const spec = str(invoice.specification_id);
  if (spec !== PEPPOL_SPEC) {
    findings.push(finding(
      "PP-002",
      spec ? "Specification identifier (BT-24) does not name Peppol BIS Billing 3.0." : "Specification identifier (BT-24) is missing.",
      `Set it to ${PEPPOL_SPEC}. An XRechnung identifier is only right for German buyers.`,
      "/specification_id",
    ));
  }

  if (!hasEndpoint(invoice.supplier)) {
    findings.push(finding(
      "PP-003",
      "Seller electronic address (BT-34) is missing.",
      "Add supplier.endpoint with the scheme and the id registered on the Peppol network, e.g. scheme 0088 (GLN) or 0192.",
      "/supplier/endpoint",
    ));
  }
  if (!hasEndpoint(invoice.customer)) {
    findings.push(finding(
      "PP-004",
      "Buyer electronic address (BT-49) is missing.",
      "Add customer.endpoint with the buyer's Peppol scheme and id; the access point routes on it.",
      "/customer/endpoint",
    ));
  }

  if (!str(invoice.buyer_reference) && !str(invoice.order_reference)) {
    findings.push(finding(
      "PP-005",
      "Neither a buyer reference (BT-10) nor an order reference (BT-13) is present.",
      "Add buyer_reference (the buyer's routing reference) or order_reference (their purchase-order number).",
      "/buyer_reference",
    ));
  }

  return findings;
}

// ---------------------------------------------------------------------------
// French profile (FR-nnn): the identifier and mention rules behind France's
// e-invoicing reform (mandatory reception from 1 September 2026, issuing
// phased in after) and the Code de commerce payment mentions that a French
// B2B invoice has always carried. Offline observation of what a platform or a
// French buyer's accounts-payable would bounce; not a Plateforme Agréée's
// validator and not legal advice. Findings never repeat a typed identifier.

export const FRENCH_RULES = {
  "FR-001": "French seller has no SIREN or SIRET on the invoice.",
  "FR-002": "A SIREN or SIRET is the wrong length or fails its Luhn check digit.",
  "FR-003": "The SIREN inside the seller's French VAT number differs from the seller's SIREN or SIRET.",
  "FR-004": "French buyer has no SIREN or SIRET, so the invoice cannot be routed to them.",
  "FR-005": "Late-payment penalty rate mention is missing (Code de commerce L441-10).",
  "FR-006": "Fixed 40 euro recovery indemnity mention is missing (Code de commerce D441-5).",
  "FR-007": "Early-payment discount (escompte) mention is missing (Code de commerce L441-9).",
};

function digitsOnly(value) {
  return String(value ?? "").replace(/[\s.\-]/g, "");
}

function luhnValid(digits) {
  if (!/^\d+$/.test(digits)) return false;
  let sum = 0;
  let double = false;
  for (let i = digits.length - 1; i >= 0; i--) {
    let d = Number(digits[i]);
    if (double) { d *= 2; if (d > 9) d -= 9; }
    sum += d;
    double = !double;
  }
  return sum % 10 === 0;
}

/** SIREN: 9 digits, Luhn. SIRET: 14 digits, Luhn, except La Poste's SIREN
 *  356000000, whose establishments only need a digit sum divisible by 5. */
export function sirenValid(value) {
  const d = digitsOnly(value);
  return d.length === 9 && luhnValid(d);
}

export function siretValid(value) {
  const d = digitsOnly(value);
  if (d.length !== 14 || !/^\d+$/.test(d)) return false;
  if (d.startsWith("356000000")) return [...d].reduce((s, c) => s + Number(c), 0) % 5 === 0;
  return luhnValid(d);
}

function legalIdOf(party) {
  if (!isObject(party)) return "";
  const raw = party.legal_id;
  const id = isObject(raw) ? raw.id : raw;
  return digitsOnly(typeof id === "string" || typeof id === "number" ? id : "");
}

function isFrench(party) {
  if (!isObject(party)) return false;
  return str(party.country).toUpperCase() === "FR" || /^FR/i.test(str(party.vat_id));
}

function noteText(invoice) {
  const notes = Array.isArray(invoice.notes) ? invoice.notes : [];
  const payment = isObject(invoice.payment) ? invoice.payment : {};
  return [...notes, payment.terms_text].filter((n) => typeof n === "string").join("\n");
}

export function inspectFrenchProfile(invoice) {
  if (!isObject(invoice)) return [];
  const findings = [];
  const supplier = isObject(invoice.supplier) ? invoice.supplier : {};
  const customer = isObject(invoice.customer) ? invoice.customer : {};

  const sellerId = legalIdOf(supplier);
  const buyerId = legalIdOf(customer);
  const sellerFrench = isFrench(supplier);

  if (sellerFrench && !sellerId) {
    findings.push(finding(
      "FR-001",
      "French seller has no SIREN or SIRET (legal registration identifier, BT-30).",
      "Add supplier.legal_id with the 9-digit SIREN or 14-digit SIRET (scheme 0002). The reform's directory routes on it.",
      "/supplier/legal_id",
    ));
  }
  if (isFrench(customer) && !buyerId) {
    findings.push(finding(
      "FR-004",
      "French buyer has no SIREN or SIRET (BT-47), so a platform cannot route the invoice to them.",
      "Add customer.legal_id with the buyer's SIREN or SIRET (scheme 0002); ask them for it, it is on their Kbis.",
      "/customer/legal_id",
    ));
  }

  for (const [role, id, path] of [["Seller", sellerId, "/supplier/legal_id"], ["Buyer", buyerId, "/customer/legal_id"]]) {
    if (id && !(sirenValid(id) || siretValid(id))) {
      findings.push(finding(
        "FR-002",
        `${role} SIREN/SIRET is not 9 or 14 digits or fails its Luhn check digit.`,
        "Copy the number again from the Kbis or the INSEE avis de situation; one wrong digit fails the check.",
        path,
      ));
    }
  }

  const vat = digitsOnly(str(supplier.vat_id).replace(/^FR/i, ""));
  if (/^FR/i.test(str(supplier.vat_id)) && sellerId && vat.length === 11 && (sirenValid(sellerId) || siretValid(sellerId))) {
    if (vat.slice(2) !== sellerId.slice(0, 9)) {
      findings.push(finding(
        "FR-003",
        "The SIREN inside the seller's French VAT number is not the seller's SIREN.",
        "A French VAT number is FR, two key digits, then the SIREN. Check that VAT number and legal_id belong to the same company.",
        "/supplier/vat_id",
      ));
    }
  }

  const isCredit = str(invoice.document_type) === "credit_note";
  if (sellerFrench && !isCredit) {
    const text = noteText(invoice);
    if (!/#PMD#|p[eé]nalit|late[- ]payment|taux d'int[eé]r[eê]t/i.test(text)) {
      findings.push(finding(
        "FR-005",
        "No late-payment penalty rate is stated (L441-10).",
        "Add a note such as: Pénalités de retard : taux BCE + 10 points (minimum three times the legal interest rate). Factur-X uses subject code PMD.",
        "/notes",
      ));
    }
    if (!/#PMT#|recouvrement|indemnit|recovery/i.test(text)) {
      findings.push(finding(
        "FR-006",
        "No fixed recovery indemnity is stated (D441-5).",
        "Add a note such as: Indemnité forfaitaire pour frais de recouvrement : 40 €. Factur-X uses subject code PMT.",
        "/notes",
      ));
    }
    if (!/#AAB#|escompte|early[- ]payment|discount/i.test(text)) {
      findings.push(finding(
        "FR-007",
        "No early-payment discount (escompte) condition is stated (L441-9).",
        "Add a note such as: Pas d'escompte pour paiement anticipé (or the rate you grant). Factur-X uses subject code AAB.",
        "/notes",
      ));
    }
  }
  return findings;
}

reference.mjs.text:
// Offline buyer / purchase-order reference (BT-10 / BT-13) observations.
// Mirrors src/einvoice_preflight/reference.py. Findings never repeat the
// typed reference. This is a shape and consistency check, not a Peppol
// profile determination.

const MAX_LENGTH = 70;
const PLACEHOLDERS = new Set(["na", "none", "null", "tbd", "todo", "unknown", "-", "--", "..."]);

function finding(rule, message, fix, path) {
  return { rule, message, fix, path };
}

export function normalizeReference(value) {
  if (typeof value !== "string") return null;
  const stripped = value.trim();
  return stripped || null;
}

export function looksLikePlaceholder(value) {
  const compact = normalizeReference(value);
  if (compact === null) return false;
  const token = compact.toLowerCase().replace(/[^a-z0-9.-]/g, "");
  if (PLACEHOLDERS.has(token)) return true;
  const letters = compact.toLowerCase().replace(/[^a-z0-9]/g, "");
  return PLACEHOLDERS.has(letters);
}

export function inspectCommercialReferences(invoice) {
  if (!invoice || typeof invoice !== "object" || Array.isArray(invoice)) return [];
  const findings = [];
  if ("buyer_reference" in invoice) {
    findings.push(...checkExplicit(
      invoice.buyer_reference,
      "INV-047",
      "/buyer_reference",
      "Buyer reference",
      "Add buyer_reference as the cost-center or buyer text, or omit buyer_reference.",
    ));
  }
  if ("order_reference" in invoice) {
    const orderFindings = checkExplicit(
      invoice.order_reference,
      "INV-048",
      "/order_reference",
      "Purchase-order reference",
      "Add order_reference as the buyer purchase-order number, or omit order_reference.",
    );
    findings.push(...orderFindings);
    if (orderFindings.length === 0 && sameReference(invoice.order_reference, invoice.invoice_number)) {
      findings.push(finding(
        "INV-049",
        "Purchase-order reference repeats the invoice number.",
        "Set order_reference to the buyer purchase-order number, or omit order_reference.",
        "/order_reference",
      ));
    }
  }
  return findings;
}

function checkExplicit(value, rule, path, label, omitFix) {
  if (typeof value !== "string" || !value.trim()) {
    return [finding(rule, `${label} is empty or not text.`, omitFix, path)];
  }
  const stripped = value.trim();
  if (stripped.length > MAX_LENGTH) {
    return [finding(
      rule,
      `${label} is longer than the usual 70-character network field.`,
      `Shorten the ${label.toLowerCase()} so a receiving system can store it, or omit the field.`,
      path,
    )];
  }
  if (looksLikePlaceholder(value)) {
    return [finding(rule, `${label} is a placeholder, not a buyer or purchase-order number.`, omitFix, path)];
  }
  return [];
}

function sameReference(left, right) {
  const first = normalizeReference(left);
  const second = normalizeReference(right);
  if (first === null || second === null) return false;
  return first.toLowerCase() === second.toLowerCase();
}

remittance.mjs.text:
// Offline remittance / payment-reference observations.
// Typo catch only — not a bank lookup and not a claim that a payment will match.

import { looksLikeCompleteIban } from "./iban.mjs";

const UNSTRUCTURED_MAX = 140;

function finding(rule, message, fix, path) {
  return { rule, message, fix, path };
}

export function normalizeRemittance(value) {
  if (typeof value !== "string") return null;
  const compact = value.toUpperCase().replace(/[^A-Z0-9]/g, "");
  return compact || null;
}

export function looksLikeStructuredRf(value) {
  const compact = normalizeRemittance(value);
  return compact !== null && classifyRf(compact) === "checksum";
}

function classifyRf(compact) {
  if (!compact.startsWith("RF") || compact.length < 5 || compact.length > 25) return "unknown";
  const check = compact.slice(2, 4);
  const body = compact.slice(4);
  if (!/^\d{2}$/.test(check) || !/^[A-Z0-9]+$/.test(body)) return "unknown";
  return "checksum";
}

function mod97Ok(compact) {
  const rearranged = compact.slice(4) + compact.slice(0, 4);
  let numeric = "";
  for (const char of rearranged) {
    numeric += parseInt(char, 36).toString(10);
  }
  let remainder = 0;
  for (const digit of numeric) {
    remainder = (remainder * 10 + Number(digit)) % 97;
  }
  return remainder === 1;
}

function checkExplicit(value, path) {
  if (typeof value !== "string" || !value.trim()) {
    return [finding(
      "INV-031",
      "Payment remittance reference is empty or not text.",
      "Provide the remittance as text, or omit payment.remittance.",
      path,
    )];
  }
  const stripped = value.trim();
  if (stripped.length > UNSTRUCTURED_MAX) {
    return [finding(
      "INV-031",
      "Payment remittance reference is longer than the usual 140-character transfer note.",
      "Shorten the remittance so a bank transfer can carry it, or omit payment.remittance.",
      path,
    )];
  }
  const compact = normalizeRemittance(value);
  if (compact === null) {
    return [finding(
      "INV-031",
      "Payment remittance reference is empty or not text.",
      "Provide the remittance as text, or omit payment.remittance.",
      path,
    )];
  }
  if (!compact.startsWith("RF")) return [];
  const kind = classifyRf(compact);
  if (kind === "unknown") {
    return [finding(
      "INV-031",
      "Payment remittance reference is not a structured RF creditor reference.",
      "Use RF, two check digits, and up to 21 characters, or an unstructured note that does not start with RF.",
      path,
    )];
  }
  if (kind === "checksum" && !mod97Ok(compact)) {
    return [finding(
      "INV-031",
      "Payment remittance reference fails the published RF checksum.",
      "Correct the RF check digits. This is a checksum typo check, not a bank lookup.",
      path,
    )];
  }
  return [];
}

export function inspectPaymentRemittance(invoice) {
  const payment = invoice.payment;
  if (!payment || typeof payment !== "object" || Array.isArray(payment)) return [];
  const remittance = payment.remittance;
  const missing = remittance === undefined || remittance === null || remittance === ""
    || (typeof remittance === "string" && !remittance.trim());
  if (missing) {
    if (looksLikeCompleteIban(payment.iban)) {
      return [finding(
        "INV-030",
        "Payment remittance reference is missing on an invoice that already names an IBAN.",
        "Add payment.remittance so the buyer can quote it on the transfer, or omit payment.iban.",
        "/payment/remittance",
      )];
    }
    return [];
  }
  return checkExplicit(remittance, "/payment/remittance");
}

report.mjs.text:
import { checkInvoice, flagDuplicateInvoiceNumbers } from "./checks.mjs";
import { inspectXrechnungProfile, inspectPeppolProfile, inspectFrenchProfile } from "./profile.mjs";
import { looksLikeCii, parseCiiInvoice } from "./cii.mjs";
import { envelopeNote, extractEmbeddedInvoice, looksLikePdf } from "./facturx.mjs";
import { looksLikeXml, parseUblInvoice } from "./ubl.mjs";

export const DEFAULT_MAX_BYTES = 1_048_576;
export const DEFAULT_MAX_FILES = 50;

function redactValues(text) {
  return String(text).replace(/\b\d+(?:\.\d+)?\b/g, "[value]");
}

export async function inspectInvoiceSource(name, source) {
  let payload = source;
  let envelope = "";
  if (looksLikePdf(name, source)) {
    const extracted = await extractEmbeddedInvoice(source);
    payload = extracted.payload;
    const peek = typeof payload === "string" ? payload : new TextDecoder().decode(payload);
    envelope = envelopeNote(extracted.label, looksLikeCii(peek) ? "cii" : "ubl");
  }
  const text = typeof payload === "string" ? payload : new TextDecoder().decode(payload);
  let invoice;
  if (looksLikeXml(name, text) || looksLikeCii(text)) {
    invoice = looksLikeCii(text) ? parseCiiInvoice(text) : parseUblInvoice(text);
  } else {
    invoice = JSON.parse(text);
  }
  return { invoice, envelope };
}

export async function parseInvoiceSource(name, source) {
  return (await inspectInvoiceSource(name, source)).invoice;
}

export async function preflightDocuments(inputs, { maxBytes = DEFAULT_MAX_BYTES, maxFiles = DEFAULT_MAX_FILES, profile = "" } = {}) {
  const reports = [];
  const readErrors = [];
  const parsed = [];

  if (inputs.length > maxFiles) {
    return {
      reports,
      readErrors: [{
        file: "(batch)",
        error: `Batch contains ${inputs.length} invoices, exceeding the ${maxFiles}-file limit. Split the batch.`,
      }],
    };
  }

  for (const input of inputs) {
    const name = input.name || "invoice.json";
    const source = input.source ?? "";
    const bytes = typeof source === "string" ? new TextEncoder().encode(source).length : source.length;
    if (bytes > maxBytes) {
      readErrors.push({
        file: name,
        error: `File exceeds ${maxBytes} bytes; refusing to read it.`,
      });
      continue;
    }
    try {
      const { invoice, envelope } = await inspectInvoiceSource(name, source);
      const errors = checkInvoice(invoice);
      if (profile === "xrechnung") errors.push(...inspectXrechnungProfile(invoice));
      if (profile === "peppol") errors.push(...inspectPeppolProfile(invoice));
      if (profile === "france") errors.push(...inspectFrenchProfile(invoice));
      reports.push({ file: name, errors, envelope });
      parsed.push({ name, invoice });
    } catch (error) {
      readErrors.push({
        file: name,
        error: error instanceof Error ? error.message : "Invoice could not be read.",
      });
    }
  }

  const duplicates = flagDuplicateInvoiceNumbers(parsed);
  for (const report of reports) {
    if (duplicates.has(report.file)) {
      report.errors.push({
        rule: "INV-019",
        message: "Invoice number is repeated in this batch.",
        fix: "Use a unique invoice number or remove the duplicate before submission.",
        path: "/invoice_number",
      });
    }
  }

  return { reports, readErrors };
}

export function summarizePreflight({ reports, readErrors }) {
  const findings = reports.flatMap((report) => report.errors);
  const failed = reports.filter((report) => report.errors.length > 0).length;
  const ruleCounts = {};
  const ruleMessages = {};
  const ruleFixes = {};
  for (const error of findings) {
    ruleCounts[error.rule] = (ruleCounts[error.rule] || 0) + 1;
    ruleMessages[error.rule] = error.message;
    ruleFixes[error.rule] = error.fix;
  }
  return {
    status: findings.length || readErrors.length ? "fail" : "pass",
    filesChecked: reports.length,
    filesFailed: failed,
    filesPassed: reports.length - failed,
    observations: findings.length,
    readErrors: readErrors.length,
    ruleCounts,
    ruleMessages,
    ruleFixes,
  };
}

export function buildChecklist({ reports, readErrors }) {
  const summary = summarizePreflight({ reports, readErrors });
  const lines = [
    "E-invoice preflight repair checklist",
    "",
    `Status: ${summary.status === "pass" ? "PASS" : "FAIL"}`,
    `Checked: ${summary.filesChecked} invoice(s)`,
    `Observations: ${summary.observations}`,
    `Read errors: ${summary.readErrors}`,
    "",
  ];
  for (const report of reports) {
    lines.push(`[ ] Review ${report.file}`);
    if (report.envelope) lines.push(`    ${report.envelope}`);
    if (report.errors.length === 0) {
      lines.push("    No supported defects found.");
      continue;
    }
    const grouped = new Map();
    for (const error of report.errors) {
      const item = grouped.get(error.rule) || { count: 0, paths: [], message: error.message, fix: error.fix };
      item.count += 1;
      if (!item.paths.includes(error.path)) item.paths.push(error.path);
      grouped.set(error.rule, item);
    }
    for (const rule of [...grouped.keys()].sort()) {
      const item = grouped.get(rule);
      const suffix = item.count !== 1 ? ` (${item.count} occurrence(s))` : "";
      lines.push(`    - [ ] ${rule}${suffix} at ${item.paths.join(", ")}: ${redactValues(item.message)}`);
      lines.push(`      Fix: ${redactValues(item.fix)}`);
    }
  }
  if (readErrors.length) {
    lines.push("", "Unreadable inputs:");
    for (const error of readErrors) lines.push(`- [ ] Review ${error.file}: ${error.error}`);
  }
  lines.push(
    "",
    "This is a local observation checklist, not a declaration of legal validity or compliance.",
    "Review and verify each change before submitting an invoice.",
  );
  return lines.join("\n") + "\n";
}

export function buildMarkdown({ reports, readErrors }) {
  const summary = summarizePreflight({ reports, readErrors });
  const escape = (value) => String(value).replaceAll("\\", "\\\\").replaceAll("|", "\\|").replaceAll("`", "\\`");
  const lines = [
    "# E-invoice preflight",
    "",
    `Overall: **${summary.status.toUpperCase()}**`,
    `Checked: ${summary.filesChecked} invoice(s)`,
    `Passed: ${summary.filesPassed}`,
    `Failed: ${summary.filesFailed}`,
    `Observations: ${summary.observations}`,
    `Read errors: ${summary.readErrors}`,
    "",
  ];
  const rules = Object.keys(summary.ruleCounts).sort();
  if (rules.length) {
    lines.push("## Finding summary", "", "| Rule | Occurrences | Check | Recommended fix |", "| --- | ---: | --- | --- |");
    for (const rule of rules) {
      lines.push(`| \`${escape(rule)}\` | ${summary.ruleCounts[rule]} | ${escape(summary.ruleMessages[rule])} | ${escape(summary.ruleFixes[rule])} |`);
    }
    lines.push("");
  }
  for (const report of reports) {
    lines.push(`## \`${escape(report.file)}\``);
    if (report.envelope) lines.push("", report.envelope);
    if (report.errors.length === 0) {
      lines.push("", "Status: **PASS**", "", "No defects found in the supported checks.", "");
      continue;
    }
    lines.push("", "Status: **FAIL**", "");
    for (const error of report.errors) {
      lines.push(`- **${escape(error.rule)}** at \`${escape(error.path || "/")}\`: ${escape(error.message)}`);
      lines.push(`  Fix: ${escape(error.fix)}`);
    }
    lines.push("");
  }
  if (readErrors.length) {
    lines.push("## Read errors", "");
    for (const error of readErrors) lines.push(`- \`${escape(error.file)}\`: ${escape(error.error)}`);
    lines.push("");
  }
  return lines.join("\n").replace(/\n+$/, "\n");
}

export function buildJsonReport({ reports, readErrors }) {
  const summary = summarizePreflight({ reports, readErrors });
  const errors = reports.flatMap((report) => report.errors.map((error) => ({ ...error, file: report.file })));
  const fixes = Object.keys(summary.ruleCounts).sort().map((rule) => ({
    rule,
    occurrences: summary.ruleCounts[rule],
    message: summary.ruleMessages[rule],
    fix: summary.ruleFixes[rule],
  }));
  return {
    schema_version: 1,
    status: summary.status,
    exit_code: readErrors.length ? 2 : errors.length ? 1 : 0,
    files_checked: summary.filesChecked,
    files_failed: summary.filesFailed,
    observations: summary.observations,
    rules: Object.fromEntries(Object.keys(summary.ruleCounts).sort().map((rule) => [rule, summary.ruleCounts[rule]])),
    fixes,
    file: reports.length === 1 ? reports[0].file : null,
    errors,
    read_errors: readErrors,
    reports: reports.map((report) => ({
      file: report.file,
      status: report.errors.length ? "fail" : "pass",
      observations: report.errors.length,
      errors: report.errors,
    })),
  };
}

function csvCell(value) {
  const text = String(value ?? "");
  if (/[",\n\r]/.test(text)) return `"${text.replaceAll('"', '""')}"`;
  return text;
}

export function buildRemediationCsv({ reports, readErrors }) {
  const grouped = new Map();
  for (const report of reports) {
    for (const finding of report.errors) {
      const item = grouped.get(finding.rule) || {
        rule: finding.rule,
        occurrences: 0,
        message: finding.message,
        fix: finding.fix,
      };
      item.occurrences += 1;
      grouped.set(finding.rule, item);
    }
  }
  const rows = [...grouped.keys()].sort().map((rule) => grouped.get(rule));
  if (readErrors.length) {
    rows.push({
      rule: "INV-READ",
      occurrences: readErrors.length,
      message: "Invoice could not be read.",
      fix: "Resolve the read error and run the preflight again.",
    });
  }
  const header = ["rule", "occurrences", "message", "fix"];
  const lines = [
    header.join(","),
    ...rows.map((row) => header.map((key) => csvCell(row[key])).join(",")),
  ];
  return `${lines.join("\n")}\n`;
}

server.mjs.text:
// Self-hostable HTTP API for e-invoice preflight. Zero dependencies: Node 20+.
//
//   POST /v1/validate        raw body = one invoice (JSON, UBL/CII XML or a
//                            Factur-X PDF). Content-Type picks the filename
//                            extension; ?name=invoice.xml overrides it.
//     add ?profile=xrechnung to also apply the German BR-DE rules (XR-nnn),
//     or ?profile=peppol for the Peppol BIS Billing 3.0 rules (PP-nnn),
//     or ?profile=france for the French SIREN and payment-mention rules (FR-nnn)
//   POST /v1/validate/batch  {"documents":[{"name","content","encoding"?}]}
//                            encoding "base64" is for PDFs; default is text.
//   POST /v1/generate        {"draft":{...},"format":"ubl"|"cii","profile":"xrechnung"|
//                            "peppol"|"en16931"} -> { ok, errors, warnings, totals,
//                            xml, filename, preflight }. See examples/draft-invoice.json.
//   GET  /healthz            liveness probe.
//   GET  /                   the browser checker (index.html), if present.
//
// Everything runs in the deployer's own process. Nothing is stored and
// nothing is forwarded; request bodies live in memory for the length of the
// request. Configuration is by environment variable only (see README).
import { createServer } from "node:http";
import { readFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";
import { timingSafeEqual } from "node:crypto";
import { generateInvoice } from "./generate.mjs";
import { buildJsonReport, preflightDocuments } from "./report.mjs";

const HERE = dirname(fileURLToPath(import.meta.url));
const DONATE_URL = "https://buymeacoffee.com/duncanhaywood";
const DISCLAIMER =
  "Preflight checks only: not a Peppol or EN 16931 conformance validator, not tax or legal advice. " +
  "Provided as-is without warranty; review results before relying on them.";

function intEnv(env, key, fallback) {
  const n = Number.parseInt(env[key] ?? "", 10);
  return Number.isFinite(n) && n > 0 ? n : fallback;
}

function profileFrom(url) {
  const profile = url.searchParams.get("profile");
  return profile === "xrechnung" || profile === "peppol" || profile === "france" ? profile : "";
}

export function loadConfig(env = process.env) {
  return {
    port: intEnv(env, "PORT", 8080),
    apiKey: env.EINVOICE_API_KEY || "",
    maxBytes: intEnv(env, "EINVOICE_MAX_BYTES", 1_048_576),
    maxBatch: intEnv(env, "EINVOICE_MAX_BATCH", 50),
    rateLimit: intEnv(env, "EINVOICE_RATE_LIMIT_PER_MIN", 120),
    corsOrigin: env.EINVOICE_CORS_ORIGIN || "",
    serveUi: env.EINVOICE_SERVE_UI !== "0",
  };
}

const EXT = [
  [/pdf/i, "invoice.pdf"],
  [/xml/i, "invoice.xml"],
  [/json/i, "invoice.json"],
];

function nameFor(contentType, override) {
  if (override) return override.replace(/[^\w.\- ]/g, "_").slice(0, 100);
  for (const [re, name] of EXT) if (re.test(contentType || "")) return name;
  return "invoice.json";
}

function keyOk(provided, expected) {
  const a = Buffer.from(provided);
  const b = Buffer.from(expected);
  return a.length === b.length && timingSafeEqual(a, b);
}

class HttpError extends Error {
  constructor(status, message) {
    super(message);
    this.status = status;
  }
}

async function readBody(req, limit) {
  const chunks = [];
  let size = 0;
  for await (const chunk of req) {
    size += chunk.length;
    if (size > limit) throw new HttpError(413, `Body exceeds ${limit} bytes.`);
    chunks.push(chunk);
  }
  return Buffer.concat(chunks);
}

export function createApp(config = loadConfig()) {
  const hits = new Map();

  function limited(ip, now) {
    const windowStart = now - 60_000;
    const recent = (hits.get(ip) || []).filter((t) => t > windowStart);
    recent.push(now);
    hits.set(ip, recent);
    if (hits.size > 5000) for (const [k, v] of hits) if (!v.some((t) => t > windowStart)) hits.delete(k);
    return recent.length > config.rateLimit;
  }

  function send(res, status, body, extra = {}) {
    const isText = typeof body === "string";
    const headers = {
      "content-type": isText ? "text/html; charset=utf-8" : "application/json; charset=utf-8",
      "cache-control": "no-store",
      "x-content-type-options": "nosniff",
      ...extra,
    };
    if (config.corsOrigin) headers["access-control-allow-origin"] = config.corsOrigin;
    res.writeHead(status, headers);
    res.end(isText ? body : JSON.stringify(body));
  }

  async function handle(req, res) {
    const url = new URL(req.url, "http://localhost");
    const path = url.pathname;

    if (req.method === "OPTIONS") {
      send(res, 204, "", {
        "access-control-allow-methods": "POST, GET, OPTIONS",
        "access-control-allow-headers": "authorization, content-type",
      });
      return;
    }
    if (req.method === "GET" && path === "/healthz") {
      send(res, 200, { status: "ok", donate: DONATE_URL });
      return;
    }
    if (req.method === "GET" && path === "/create.html" && config.serveUi) {
      try {
        send(res, 200, await readFile(join(HERE, "create.html"), "utf8"));
      } catch {
        send(res, 404, { error: "UI not bundled in this deployment." });
      }
      return;
    }
    if (req.method === "GET" && (path === "/" || path === "/index.html") && config.serveUi) {
      try {
        send(res, 200, await readFile(join(HERE, "index.html"), "utf8"));
      } catch {
        send(res, 404, { error: "UI not bundled in this deployment." });
      }
      return;
    }
    if (!path.startsWith("/v1/")) {
      send(res, 404, { error: "Not found." });
      return;
    }

    if (config.apiKey) {
      const m = /^Bearer (.+)$/.exec(req.headers.authorization || "");
      if (!m || !keyOk(m[1], config.apiKey)) {
        send(res, 401, { error: "Missing or invalid API key." }, { "www-authenticate": "Bearer" });
        return;
      }
    }
    const ip = req.headers["x-forwarded-for"]?.split(",")[0].trim() || req.socket.remoteAddress || "?";
    if (limited(ip, Date.now())) {
      send(res, 429, { error: "Rate limit exceeded." }, { "retry-after": "60" });
      return;
    }
    if (req.method !== "POST") {
      send(res, 405, { error: "Use POST." }, { allow: "POST" });
      return;
    }

    if (path === "/v1/validate") {
      const body = await readBody(req, config.maxBytes);
      if (!body.length) throw new HttpError(400, "Empty body.");
      const name = nameFor(req.headers["content-type"], url.searchParams.get("name"));
      const source = name.toLowerCase().endsWith(".pdf") ? new Uint8Array(body) : body.toString("utf8");
      const result = await preflightDocuments([{ name, source }], { maxBytes: config.maxBytes, maxFiles: 1, profile: profileFrom(url) });
      const report = buildJsonReport(result);
      send(res, 200, { ...report, disclaimer: DISCLAIMER });
      return;
    }

    if (path === "/v1/validate/batch") {
      // Base64 inflates by a third, so allow for it on the envelope.
      const raw = await readBody(req, Math.ceil(config.maxBytes * config.maxBatch * 1.4) + 4096);
      let parsed;
      try {
        parsed = JSON.parse(raw.toString("utf8"));
      } catch {
        throw new HttpError(400, "Body must be JSON.");
      }
      const docs = parsed?.documents;
      if (!Array.isArray(docs) || !docs.length) throw new HttpError(400, 'Expected {"documents":[...]}.');
      if (docs.length > config.maxBatch) throw new HttpError(413, `At most ${config.maxBatch} documents per batch.`);
      const inputs = docs.map((d, i) => {
        if (typeof d?.content !== "string") throw new HttpError(400, `documents[${i}].content must be a string.`);
        const name = nameFor("", d.name) || `invoice-${i}.json`;
        const source = d.encoding === "base64" ? new Uint8Array(Buffer.from(d.content, "base64")) : d.content;
        return { name: d.name ? name : `invoice-${i}.json`, source };
      });
      const result = await preflightDocuments(inputs, { maxBytes: config.maxBytes, maxFiles: config.maxBatch, profile: profileFrom(url) });
      send(res, 200, { ...buildJsonReport(result), disclaimer: DISCLAIMER });
      return;
    }

    if (path === "/v1/generate") {
      const raw = await readBody(req, config.maxBytes);
      let parsed;
      try {
        parsed = JSON.parse(raw.toString("utf8"));
      } catch {
        throw new HttpError(400, "Body must be JSON.");
      }
      if (!parsed || typeof parsed !== "object" || typeof parsed.draft !== "object" || parsed.draft === null) {
        throw new HttpError(400, 'Expected {"draft":{...}}.');
      }
      const made = generateInvoice(parsed.draft, { format: parsed.format || "ubl", profile: parsed.profile || "xrechnung" });
      if (!made.ok) {
        send(res, 422, { ...made, disclaimer: DISCLAIMER });
        return;
      }
      const check = buildJsonReport(await preflightDocuments([{ name: made.filename, source: made.xml }], { maxBytes: config.maxBytes, maxFiles: 1 }));
      send(res, 200, { ...made, preflight: { status: check.status, findings: check.errors }, disclaimer: DISCLAIMER });
      return;
    }

    send(res, 404, { error: "Not found." });
  }

  return createServer((req, res) => {
    handle(req, res).catch((err) => {
      if (err instanceof HttpError) send(res, err.status, { error: err.message });
      else send(res, 500, { error: "Internal error." });
    });
  });
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const config = loadConfig();
  createApp(config).listen(config.port, () => {
    console.log(`einvoice-preflight API on :${config.port}${config.apiKey ? " (API key required)" : " (open: set EINVOICE_API_KEY to require a key)"}`);
  });
}

src/einvoice_preflight/adjustment.py.text:
"""Offline header allowance / charge (BT-92 / BT-99) observations.

A document-level discount or surcharge whose amount does not match its
percent of the base, or that has no reason, is a common ERP export
mistake. Access points then reject the file after the bookkeeper already
sent it. This is arithmetic and shape, not a Peppol profile determination
and not a claim that the discount is commercially correct. Findings never
repeat the amount, percent, or reason. Line-level AllowanceCharge is
ignored.
"""

from __future__ import annotations

from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from typing import Any

from .reference import looks_like_placeholder

_MAX_REASON = 100


def _money(value: Any) -> Decimal | None:
    parsed = _number(value)
    return parsed.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP) if parsed is not None else None


def _number(value: Any) -> Decimal | None:
    try:
        result = Decimal(str(value))
    except (InvalidOperation, ValueError, TypeError):
        return None
    return result if result.is_finite() else None


def normalize_kind(value: Any) -> str | None:
    """Return allowance or charge, or None when empty / unknown."""
    if isinstance(value, bool):
        return "charge" if value else "allowance"
    if not isinstance(value, str):
        return None
    compact = value.strip().casefold()
    if compact in {"true", "1", "charge", "surcharge"}:
        return "charge"
    if compact in {"false", "0", "allowance", "discount"}:
        return "allowance"
    return None


def header_adjustment_net_delta(invoice: dict[str, Any]) -> Decimal:
    """Charges minus allowances for rows with a usable amount. Others are 0."""
    delta = Decimal("0.00")
    for row in _rows(invoice):
        if not isinstance(row, dict):
            continue
        kind = normalize_kind(row.get("kind"))
        amount = _money(row.get("amount"))
        if kind is None or amount is None or amount < 0:
            continue
        if kind == "charge":
            delta += amount
        else:
            delta -= amount
    return delta.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)


def inspect_header_adjustments(invoice: dict[str, Any]) -> list[dict[str, str]]:
    """Return INV-050 / INV-051 / INV-052 observations for optional rows."""
    if not isinstance(invoice, dict) or "adjustments" not in invoice:
        return []
    raw = invoice.get("adjustments")
    if raw in (None, ""):
        return [_finding(
            "INV-050",
            "Header allowance or charge list is empty or not a list of rows.",
            "Add adjustments as a list of allowance or charge rows, or omit adjustments.",
            "/adjustments",
        )]
    if not isinstance(raw, list):
        return [_finding(
            "INV-050",
            "Header allowance or charge list is empty or not a list of rows.",
            "Add adjustments as a list of allowance or charge rows, or omit adjustments.",
            "/adjustments",
        )]
    findings: list[dict[str, str]] = []
    for index, row in enumerate(raw):
        findings.extend(_inspect_row(row, index))
    return findings


def _rows(invoice: dict[str, Any]) -> list[Any]:
    raw = invoice.get("adjustments") if isinstance(invoice, dict) else None
    return raw if isinstance(raw, list) else []


def _inspect_row(row: Any, index: int) -> list[dict[str, str]]:
    path = f"/adjustments/{index}"
    if not isinstance(row, dict):
        return [_finding(
            "INV-050",
            "Header allowance or charge row is not an object.",
            "Provide kind, amount, and a reason, or omit the row.",
            path,
        )]
    findings: list[dict[str, str]] = []
    kind = normalize_kind(row.get("kind")) if "kind" in row else None
    if "kind" in row and kind is None:
        findings.append(_finding(
            "INV-050",
            "Header allowance or charge kind is missing or not allowance or charge.",
            "Set kind to allowance or charge, or omit the row.",
            f"{path}/kind",
        ))
    elif "kind" not in row:
        findings.append(_finding(
            "INV-050",
            "Header allowance or charge kind is missing or not allowance or charge.",
            "Set kind to allowance or charge, or omit the row.",
            f"{path}/kind",
        ))

    if "amount" not in row or row.get("amount") in (None, ""):
        findings.append(_finding(
            "INV-050",
            "Header allowance or charge amount is missing or invalid.",
            "Provide a non-negative amount, or omit the row.",
            f"{path}/amount",
        ))
        amount = None
    else:
        amount = _money(row.get("amount"))
        if amount is None or amount < 0:
            findings.append(_finding(
                "INV-050",
                "Header allowance or charge amount is missing or invalid.",
                "Provide a non-negative amount, or omit the row.",
                f"{path}/amount",
            ))
            amount = None

    base = None
    percent = None
    if "base" in row and row.get("base") not in (None, ""):
        base = _money(row.get("base"))
        if base is None or base < 0:
            findings.append(_finding(
                "INV-051",
                "Header allowance or charge base is missing or invalid.",
                "Provide a non-negative base amount, or omit base and percent.",
                f"{path}/base",
            ))
            base = None
    if "percent" in row and row.get("percent") not in (None, ""):
        percent = _number(row.get("percent"))
        if percent is None or percent < 0 or percent > 100:
            findings.append(_finding(
                "INV-051",
                "Header allowance or charge percentage is missing or invalid.",
                "Use a percentage between 0 and 100, or omit percent and base.",
                f"{path}/percent",
            ))
            percent = None
    if amount is not None and base is not None and percent is not None:
        expected = (base * percent / Decimal("100")).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        if amount != expected:
            findings.append(_finding(
                "INV-051",
                "Header allowance or charge amount does not match its percentage of the base.",
                f"Set the amount to {expected} or correct percent and base.",
                f"{path}/amount",
            ))

    if "reason" in row or "reason_code" in row:
        reason = row.get("reason")
        code = row.get("reason_code")
        has_reason = isinstance(reason, str) and reason.strip() and not looks_like_placeholder(reason)
        has_code = isinstance(code, str) and code.strip() and not looks_like_placeholder(code)
        if isinstance(reason, str) and len(reason.strip()) > _MAX_REASON:
            findings.append(_finding(
                "INV-052",
                "Header allowance or charge reason is longer than the usual 100-character network field.",
                "Shorten the reason so a receiving system can store it, or omit the row.",
                f"{path}/reason",
            ))
        elif not has_reason and not has_code:
            findings.append(_finding(
                "INV-052",
                "Header allowance or charge reason is empty or a placeholder.",
                "Add a settlement or packing reason, or omit reason and reason_code.",
                f"{path}/reason" if "reason" in row else f"{path}/reason_code",
            ))
    else:
        findings.append(_finding(
            "INV-052",
            "Header allowance or charge has no reason.",
            "Add a reason such as a settlement or packing description, or omit the row.",
            f"{path}/reason",
        ))
    return findings


def _finding(rule: str, message: str, fix: str, path: str) -> dict[str, str]:
    return {"rule": rule, "message": message, "fix": fix, "path": path}

src/einvoice_preflight/bic.py.text:
"""Offline BIC shape and IBAN-country observations.

This is a typo catch for payment instructions, not a bank lookup and not a
determination that an institution exists, belongs to the named party, or
may receive funds. Short internal bank codes are left alone unless they
are placed in payment.bic.
"""

from __future__ import annotations

from typing import Any

from .iban import looks_like_complete_iban, normalize_iban


def normalize_bic(value: Any) -> str | None:
    """Uppercase and strip separators. Empty or non-text becomes None."""
    if not isinstance(value, str):
        return None
    compact = "".join(ch for ch in value.upper() if ch.isalnum())
    return compact or None


def looks_like_complete_bic(value: Any) -> bool:
    """True when the value is an 8- or 11-character ISO 9362 BIC."""
    compact = normalize_bic(value)
    return compact is not None and _classify(compact) == "ok"


def inspect_payment_bic(invoice: dict[str, Any]) -> list[dict[str, str]]:
    """Return INV-026 / INV-027 observations for an optional payment BIC."""
    payment = invoice.get("payment")
    if not isinstance(payment, dict):
        return []
    bic = payment.get("bic")
    if bic in (None, ""):
        return []
    findings = _check_explicit(bic, "/payment/bic")
    if findings:
        return findings
    return _country_mismatch(payment)


def _check_explicit(value: Any, path: str) -> list[dict[str, str]]:
    if not isinstance(value, str) or not value.strip():
        return [_finding(
            "INV-026",
            "Payment BIC is empty or not text.",
            "Provide the BIC as text, or omit payment.bic.",
            path,
        )]
    compact = normalize_bic(value)
    if compact is None:
        return [_finding(
            "INV-026",
            "Payment BIC is empty or not text.",
            "Provide the BIC as text, or omit payment.bic.",
            path,
        )]
    kind = _classify(compact)
    if kind == "unknown":
        return [_finding(
            "INV-026",
            "Payment BIC is not an 8- or 11-character bank identifier.",
            "Use four letters, a two-letter country, a two-character location, and an optional three-character branch, or omit payment.bic.",
            path,
        )]
    return []


def _country_mismatch(payment: dict[str, Any]) -> list[dict[str, str]]:
    """Flag a complete BIC whose country is not the complete IBAN country."""
    compact_bic = normalize_bic(payment.get("bic"))
    compact_iban = normalize_iban(payment.get("iban"))
    if compact_bic is None or compact_iban is None:
        return []
    if not looks_like_complete_bic(compact_bic) or not looks_like_complete_iban(compact_iban):
        return []
    bic_country = compact_bic[4:6]
    iban_country = compact_iban[:2]
    if bic_country == iban_country:
        return []
    return [_finding(
        "INV-027",
        "Payment BIC country does not match the payment IBAN country.",
        "Correct the BIC or the IBAN so both use the same country, or omit payment.bic.",
        "/payment/bic",
    )]


def _classify(compact: str) -> str:
    # ISO 9362: BBBBCCLL or BBBBCCLLBBB. Bank letters, country letters,
    # location and optional branch alphanumeric. No checksum is published.
    if len(compact) not in {8, 11}:
        return "unknown"
    bank, country, location = compact[:4], compact[4:6], compact[6:8]
    branch = compact[8:]
    if not bank.isalpha() or not country.isalpha():
        return "unknown"
    if not location.isalnum() or (branch and not branch.isalnum()):
        return "unknown"
    return "ok"


def _finding(rule: str, message: str, fix: str, path: str) -> dict[str, str]:
    return {"rule": rule, "message": message, "fix": fix, "path": path}

src/einvoice_preflight/breakdown.py.text:
"""Offline mixed-rate tax-breakdown observations.

Peppol and many EN 16931 CIUS require a TaxSubtotal per rate when an
invoice mixes standard, reduced, and zero-rated lines. An ERP export
that only carries a header tax total is a common rejection after the
bookkeeper already sent the file. This is arithmetic and document-shape
checking, not a tax-law determination and not a claim that a rate is
correct. Findings never repeat invoice numbers or line descriptions.
"""

from __future__ import annotations

from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from typing import Any


def inspect_tax_breakdown(invoice: dict[str, Any]) -> list[dict[str, str]]:
    """Return INV-037 / INV-038 observations for tax_breakdown."""
    if not isinstance(invoice, dict):
        return []
    expected = _line_groups(invoice.get("lines"))
    supplied = invoice.get("tax_breakdown")
    missing = "tax_breakdown" not in invoice or supplied in (None, "")
    if missing or supplied == []:
        if len(expected) > 1:
            return [_finding(
                "INV-037",
                "Invoice mixes tax rates without a per-rate tax breakdown.",
                "Add tax_breakdown with one row per rate (tax_percent, taxable, tax), or use a single tax percentage.",
                "/tax_breakdown",
            )]
        return []
    if not isinstance(supplied, list):
        return [_finding(
            "INV-038",
            "Tax breakdown is not a list of per-rate rows.",
            "Provide tax_breakdown as an array of objects with tax_percent, taxable, and tax.",
            "/tax_breakdown",
        )]
    return _check_rows(supplied, expected)


def _line_groups(lines: Any) -> dict[Decimal, dict[str, Decimal]]:
    groups: dict[Decimal, dict[str, Decimal]] = {}
    if not isinstance(lines, list):
        return groups
    for line in lines:
        if not isinstance(line, dict):
            continue
        quantity, price, tax = _number(line.get("quantity")), _money(line.get("unit_price")), _number(line.get("tax_percent"))
        if quantity is None or quantity <= 0 or price is None or price < 0:
            continue
        if tax is None or tax < 0 or tax > 100:
            continue
        line_net = (quantity * price).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        line_tax = (line_net * tax / Decimal("100")).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        bucket = groups.setdefault(tax, {"taxable": Decimal("0.00"), "tax": Decimal("0.00")})
        bucket["taxable"] += line_net
        bucket["tax"] += line_tax
    return groups


def _check_rows(rows: list[Any], expected: dict[Decimal, dict[str, Decimal]]) -> list[dict[str, str]]:
    findings: list[dict[str, str]] = []
    seen: dict[Decimal, int] = {}
    for index, row in enumerate(rows):
        path = f"/tax_breakdown/{index}"
        if not isinstance(row, dict):
            findings.append(_finding(
                "INV-038",
                f"Tax breakdown row {index + 1} is not an object.",
                "Provide tax_percent, taxable, and tax on each breakdown row.",
                path,
            ))
            continue
        percent = _number(row.get("tax_percent"))
        taxable = _money(row.get("taxable"))
        tax = _money(row.get("tax"))
        if percent is None or percent < 0 or percent > 100:
            findings.append(_finding(
                "INV-038",
                f"Tax breakdown row {index + 1} tax percentage is missing or invalid.",
                "Use the tax percentage supplied by your authoritative source; this tool does not choose it.",
                f"{path}/tax_percent",
            ))
            continue
        if percent in seen:
            findings.append(_finding(
                "INV-038",
                "Tax breakdown repeats the same tax percentage on more than one row.",
                "Keep one breakdown row per tax percentage.",
                f"{path}/tax_percent",
            ))
            continue
        seen[percent] = index
        if taxable is None or taxable < 0:
            findings.append(_finding(
                "INV-038",
                f"Tax breakdown row {index + 1} taxable amount is missing or invalid.",
                "Set taxable to the net of the lines at this rate.",
                f"{path}/taxable",
            ))
            continue
        if tax is None or tax < 0:
            findings.append(_finding(
                "INV-038",
                f"Tax breakdown row {index + 1} tax amount is missing or invalid.",
                "Set tax to taxable times the row percentage, rounded to cents.",
                f"{path}/tax",
            ))
            continue
        expected_tax = (taxable * percent / Decimal("100")).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        if tax != expected_tax:
            findings.append(_finding(
                "INV-038",
                f"Tax breakdown row {index + 1} tax amount does not equal taxable times the percentage.",
                f"Set tax to {expected_tax} or correct taxable and tax_percent.",
                f"{path}/tax",
            ))
        group = expected.get(percent)
        if group is None:
            findings.append(_finding(
                "INV-038",
                f"Tax breakdown row {index + 1} names a tax percentage that no line uses.",
                "Remove the extra row, or correct the line tax percentages.",
                f"{path}/tax_percent",
            ))
            continue
        if taxable != group["taxable"]:
            findings.append(_finding(
                "INV-038",
                f"Tax breakdown row {index + 1} taxable amount does not match the lines at that rate.",
                f"Set taxable to {group['taxable']} or correct the line nets.",
                f"{path}/taxable",
            ))
    for percent in expected:
        if percent not in seen:
            findings.append(_finding(
                "INV-038",
                "Tax breakdown is missing a row for a tax percentage used on the lines.",
                "Add one breakdown row per line tax percentage.",
                "/tax_breakdown",
            ))
    return findings


def _money(value: Any) -> Decimal | None:
    result = _number(value)
    return result.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP) if result is not None else None


def _number(value: Any) -> Decimal | None:
    try:
        result = Decimal(str(value))
    except (InvalidOperation, ValueError, TypeError):
        return None
    return result if result.is_finite() else None


def _finding(rule: str, message: str, fix: str, path: str) -> dict[str, str]:
    return {"rule": rule, "message": message, "fix": fix, "path": path}

src/einvoice_preflight/checks.py.text:
from __future__ import annotations

from datetime import date
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from typing import Any

from .adjustment import header_adjustment_net_delta, inspect_header_adjustments
from .bic import inspect_payment_bic
from .breakdown import inspect_tax_breakdown
from .document import inspect_document_type
from .endpoint import inspect_party_endpoint
from .iban import inspect_payment_iban
from .means import inspect_payment_means
from .period import inspect_invoice_period
from .reference import inspect_commercial_references
from .remittance import inspect_payment_remittance
from .tax import inspect_tax_exemption
from .terms import inspect_payment_terms
from .vat import inspect_party_vat


def _money(value: Any) -> Decimal | None:
    result = _number(value)
    return result.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP) if result is not None else None


def _number(value: Any) -> Decimal | None:
    """Parse a finite number without applying currency-specific rounding."""
    try:
        result = Decimal(str(value))
    except (InvalidOperation, ValueError, TypeError):
        return None
    return result if result.is_finite() else None


def _iso_date(value: Any) -> date | None:
    """Accept the documented extended YYYY-MM-DD form only."""
    if not isinstance(value, str) or len(value) != 10 or value[4] != "-" or value[7] != "-":
        return None
    try:
        return date.fromisoformat(value)
    except ValueError:
        return None


def check_invoice(invoice: Any) -> list[dict[str, str]]:
    errors: list[dict[str, str]] = []

    def fail(rule: str, message: str, fix: str, path: str = "") -> None:
        errors.append({"rule": rule, "message": message, "fix": fix, "path": path})

    if not isinstance(invoice, dict):
        return [{"rule": "INV-001", "message": "Invoice must be a JSON object.", "fix": "Provide the invoice object at the document root.", "path": ""}]
    for field in ("invoice_number", "issue_date", "currency", "supplier", "customer", "lines", "totals"):
        if field not in invoice:
            fail("INV-001", f"Required field '{field}' is missing.", f"Add a '{field}' field.", f"/{field}")
    if not isinstance(invoice.get("invoice_number"), str) or not invoice.get("invoice_number", "").strip():
        fail("INV-002", "Invoice number is empty or not text.", "Provide a non-empty invoice number.", "/invoice_number")
    issue_date = _iso_date(invoice.get("issue_date"))
    if issue_date is None:
        fail("INV-003", "Issue date is not an ISO date.", "Use YYYY-MM-DD, for example 2026-08-24.", "/issue_date")
    if "due_date" in invoice and invoice.get("due_date") not in (None, ""):
        due_date = _iso_date(invoice["due_date"])
        if due_date is None:
            fail("INV-020", "Due date is not an ISO date.", "Use YYYY-MM-DD, for example 2026-09-23.", "/due_date")
        if due_date is not None and issue_date is not None and due_date < issue_date:
            fail("INV-021", "Due date is earlier than the issue date.", "Set due date to the issue date or a later date.", "/due_date")
    if not isinstance(invoice.get("currency"), str) or len(invoice.get("currency", "")) != 3 or not invoice.get("currency", "").isupper():
        fail("INV-004", "Currency is not a three-letter uppercase code.", "Use an ISO-style code such as EUR or GBP.", "/currency")
    for party_name in ("supplier", "customer"):
        party = invoice.get(party_name)
        if not isinstance(party, dict) or not isinstance(party.get("id"), str) or not party.get("id", "").strip():
            fail("INV-005", f"{party_name.title()} identifier is missing.", f"Add the {party_name} identifier from the source system.", f"/{party_name}/id")
        if not isinstance(party, dict) or not isinstance(party.get("name"), str) or not party.get("name", "").strip():
            fail("INV-006", f"{party_name.title()} name is missing.", f"Add the {party_name} name.", f"/{party_name}/name")
        if isinstance(party, dict):
            for finding in inspect_party_vat(party, party_name):
                fail(finding["rule"], finding["message"], finding["fix"], finding["path"])
            for finding in inspect_party_endpoint(party, party_name):
                fail(finding["rule"], finding["message"], finding["fix"], finding["path"])
    for finding in inspect_payment_iban(invoice):
        fail(finding["rule"], finding["message"], finding["fix"], finding["path"])
    for finding in inspect_payment_means(invoice):
        fail(finding["rule"], finding["message"], finding["fix"], finding["path"])
    for finding in inspect_payment_terms(invoice):
        fail(finding["rule"], finding["message"], finding["fix"], finding["path"])
    for finding in inspect_payment_bic(invoice):
        fail(finding["rule"], finding["message"], finding["fix"], finding["path"])
    for finding in inspect_payment_remittance(invoice):
        fail(finding["rule"], finding["message"], finding["fix"], finding["path"])
    for finding in inspect_document_type(invoice):
        fail(finding["rule"], finding["message"], finding["fix"], finding["path"])
    for finding in inspect_tax_exemption(invoice):
        fail(finding["rule"], finding["message"], finding["fix"], finding["path"])
    for finding in inspect_tax_breakdown(invoice):
        fail(finding["rule"], finding["message"], finding["fix"], finding["path"])
    for finding in inspect_invoice_period(invoice):
        fail(finding["rule"], finding["message"], finding["fix"], finding["path"])
    for finding in inspect_commercial_references(invoice):
        fail(finding["rule"], finding["message"], finding["fix"], finding["path"])
    for finding in inspect_header_adjustments(invoice):
        fail(finding["rule"], finding["message"], finding["fix"], finding["path"])
    lines = invoice.get("lines")
    if not isinstance(lines, list) or not lines:
        fail("INV-007", "Invoice has no line items.", "Add at least one line item.", "/lines")
        lines = []
    expected_net = Decimal("0")
    expected_tax = Decimal("0")
    for index, line in enumerate(lines, 1):
        if not isinstance(line, dict):
            fail("INV-008", f"Line {index} is not an object.", "Provide description, quantity, unit_price, and tax_percent.", f"/lines/{index - 1}")
            continue
        if not isinstance(line.get("description"), str) or not line.get("description", "").strip():
            fail("INV-008", f"Line {index} has no description.", "Add a human-readable line description.", f"/lines/{index - 1}/description")
        quantity, price, tax = _number(line.get("quantity")), _money(line.get("unit_price")), _number(line.get("tax_percent"))
        if quantity is None or quantity <= 0:
            fail("INV-009", f"Line {index} quantity is invalid.", "Use a positive numeric quantity.", f"/lines/{index - 1}/quantity")
        if price is None or price < 0:
            fail("INV-010", f"Line {index} unit price is invalid.", "Use a non-negative numeric unit price.", f"/lines/{index - 1}/unit_price")
        if tax is None or tax < 0 or tax > 100:
            fail("INV-011", f"Line {index} tax percentage is invalid.", "Use the tax percentage supplied by your authoritative source; this tool does not choose it.", f"/lines/{index - 1}/tax_percent")
        if quantity is not None and price is not None and quantity > 0 and price >= 0:
            line_net = (quantity * price).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
            expected_net += line_net
            if tax is not None and 0 <= tax <= 100:
                expected_tax += (line_net * tax / Decimal("100")).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
            supplied = _money(line.get("net"))
            if supplied is None or supplied != line_net:
                fail("INV-012", f"Line {index} net is missing or does not match quantity times unit price.", f"Set line net to {line_net} or correct the inputs.", f"/lines/{index - 1}/net")
    expected_net = (expected_net + header_adjustment_net_delta(invoice)).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
    if expected_net < 0:
        expected_net = Decimal("0.00")
    totals = invoice.get("totals")
    if not isinstance(totals, dict):
        totals = {}
    net, tax_total, gross = (_money(totals.get(key)) for key in ("net", "tax", "gross"))
    if net is None or net < 0:
        fail("INV-013", "Invoice net total is missing or invalid.", "Provide a non-negative numeric net total.", "/totals/net")
    elif net != expected_net:
        if invoice.get("adjustments"):
            fail("INV-014", "Invoice net total does not match line items after header allowances and charges.", f"Set net total to {expected_net} or correct the line items and adjustments.", "/totals/net")
        else:
            fail("INV-014", "Invoice net total does not match its line items.", f"Set net total to {expected_net} or correct the line items.", "/totals/net")
    if tax_total is None or tax_total < 0:
        fail("INV-015", "Invoice tax total is missing or invalid.", "Provide a non-negative numeric tax total.", "/totals/tax")
    elif tax_total != expected_tax:
        fail("INV-018", "Invoice tax total does not match its line tax percentages.", f"Set tax total to {expected_tax} or correct the line inputs.", "/totals/tax")
    if gross is None or gross < 0:
        fail("INV-016", "Invoice gross total is missing or invalid.", "Provide a non-negative numeric gross total.", "/totals/gross")
    elif net is not None and tax_total is not None and gross != net + tax_total:
        fail("INV-017", "Gross total does not equal net plus tax.", f"Set gross total to {net + tax_total} or correct the totals.", "/totals/gross")
    prepaid = _optional_money(totals, "prepaid")
    if prepaid is not None:
        if prepaid < 0:
            fail("INV-028", "Prepaid amount is missing or invalid.", "Provide a non-negative numeric prepaid amount, or omit totals.prepaid.", "/totals/prepaid")
        elif gross is not None and gross >= 0 and prepaid > gross:
            fail("INV-028", "Prepaid amount is greater than the invoice gross.", f"Set prepaid to at most {gross} or correct the totals.", "/totals/prepaid")
    due = _optional_money(totals, "due")
    if due is not None:
        if due < 0:
            fail("INV-029", "Amount due is missing or invalid.", "Provide a non-negative numeric amount due, or omit totals.due.", "/totals/due")
        elif gross is not None and gross >= 0 and (prepaid is None or prepaid >= 0):
            applied = prepaid if prepaid is not None and prepaid >= 0 else Decimal("0")
            expected_due = (gross - applied).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
            if expected_due < 0:
                expected_due = Decimal("0.00")
            if due != expected_due:
                fail("INV-029", "Amount due does not equal gross minus prepaid.", f"Set amount due to {expected_due} or correct prepaid and gross.", "/totals/due")
    return errors


def _optional_money(totals: dict[str, Any], key: str) -> Decimal | None:
    """Parse an optional money field. Missing or blank is None; unparseable is -1."""
    if key not in totals or totals.get(key) in (None, ""):
        return None
    parsed = _money(totals.get(key))
    return parsed if parsed is not None else Decimal("-1")

