"""Offline document-type and credit-note reference observations.

A credit that travels as a commercial invoice, or that omits the invoice
it reverses, is a common ERP export mistake. Networks then reject the
file after the bookkeeper already sent it. This is a document-shape
check, not a Peppol profile determination and not a claim that a credit
is legally valid. Findings never repeat the original invoice number.
"""

from __future__ import annotations

from typing import Any

# UN/CEFACT 1001 codes commonly seen on UBL InvoiceTypeCode /
# CreditNoteTypeCode / DebitNoteTypeCode, plus the JSON names.
_TYPES = {
    "invoice": "invoice",
    "commercial invoice": "invoice",
    "corrected invoice": "invoice",
    "self billed invoice": "invoice",
    "prepayment invoice": "invoice",
    "380": "invoice",
    "384": "invoice",
    "386": "invoice",
    "389": "invoice",
    "credit note": "credit_note",
    "creditnote": "credit_note",
    "credit": "credit_note",
    "self billed credit note": "credit_note",
    "381": "credit_note",
    "261": "credit_note",
    "debit note": "debit_note",
    "debitnote": "debit_note",
    "debit": "debit_note",
    "383": "debit_note",
}

_REVERSING = frozenset({"credit_note", "debit_note"})


def normalize_document_type(value: Any) -> str | None:
    """Map a type name or UNCL 1001 code to invoice / credit_note / debit_note.

    Empty or missing becomes None. An unrecognised value becomes ``invalid``.
    """
    if value is None:
        return None
    if isinstance(value, bool):
        return "invalid"
    if isinstance(value, int):
        key = str(value)
    elif isinstance(value, str):
        key = " ".join(value.strip().lower().replace("_", " ").replace("-", " ").split())
        if not key:
            return None
    else:
        return "invalid"
    if key in _TYPES:
        return _TYPES[key]
    compact = key.replace(" ", "")
    return _TYPES.get(compact, "invalid")


def inspect_document_type(invoice: dict[str, Any]) -> list[dict[str, str]]:
    """Return INV-032 / INV-033 / INV-034 observations for document type."""
    findings: list[dict[str, str]] = []
    explicit_kind = normalize_document_type(invoice.get("document_type"))
    code_kind = normalize_document_type(invoice.get("document_code"))

    if invoice.get("document_type") not in (None, "") and explicit_kind == "invalid":
        findings.append(_finding(
            "INV-032",
            "Document type is not a known invoice, credit note, or debit note.",
            "Use invoice, credit_note, or debit_note, or omit document_type.",
            "/document_type",
        ))
    if invoice.get("document_code") not in (None, "") and code_kind == "invalid":
        findings.append(_finding(
            "INV-032",
            "Document type code is not a known invoice, credit note, or debit note code.",
            "Use a UN/CEFACT 1001 code such as 380, 381, or 383, or omit document_code.",
            "/document_code",
        ))

    if (
        explicit_kind in {"invoice", "credit_note", "debit_note"}
        and code_kind in {"invoice", "credit_note", "debit_note"}
        and explicit_kind != code_kind
    ):
        findings.append(_finding(
            "INV-034",
            "This document is marked as a commercial invoice but its type code is a credit or debit note."
            if explicit_kind == "invoice"
            else "This document's type and type code do not describe the same kind of document.",
            "Send a CreditNote when the type code is 381, or set document_type to match document_code.",
            "/document_code",
        ))

    effective = _effective_type(explicit_kind, code_kind)
    needs_original = effective in _REVERSING or (
        explicit_kind == "invoice" and code_kind in _REVERSING
    )
    if needs_original:
        original = invoice.get("original_invoice")
        missing = original in (None, "") or (isinstance(original, str) and not original.strip())
        if missing:
            findings.append(_finding(
                "INV-033",
                "Credit or debit note is missing the original invoice it reverses.",
                "Add original_invoice with the invoice number being credited or debited.",
                "/original_invoice",
            ))
        elif not isinstance(original, str):
            findings.append(_finding(
                "INV-033",
                "Original invoice reference is empty or not text.",
                "Provide original_invoice as text, or omit document_type if this is a commercial invoice.",
                "/original_invoice",
            ))
        elif _same_reference(original, invoice.get("invoice_number")):
            findings.append(_finding(
                "INV-034",
                "This credit or debit note names itself as the invoice it reverses.",
                "Set original_invoice to the invoice being credited or debited, not this document's own number.",
                "/original_invoice",
            ))
    return findings


def _effective_type(explicit_kind: str | None, code_kind: str | None) -> str:
    if explicit_kind in {"invoice", "credit_note", "debit_note"}:
        return explicit_kind
    if code_kind in {"invoice", "credit_note", "debit_note"}:
        return code_kind
    return "invoice"


def _same_reference(left: Any, right: Any) -> bool:
    if not isinstance(left, str) or not isinstance(right, str):
        return False
    return left.strip().casefold() == right.strip().casefold() and bool(left.strip())


def _finding(rule: str, message: str, fix: str, path: str) -> dict[str, str]:
    return {"rule": rule, "message": message, "fix": fix, "path": path}

src/einvoice_preflight/endpoint.py.text:
"""Offline buyer/seller electronic-address (EndpointID) observations.

Peppol and many EN 16931 CIUS reject an invoice when the buyer or seller
electronic address is missing a scheme, uses an unknown EAS code, or fails
a published identifier shape. This is a document-shape and typo catch, not
a directory lookup and not a claim that the party can receive e-invoices.
Findings never repeat the address.
"""

from __future__ import annotations

from typing import Any

# Common Peppol Electronic Address Scheme (EAS) codes. Unknown codes are
# INV-039 so a typo like 088 or 00888 is visible before the network bounce.
_KNOWN_SCHEMES = frozenset({
    "0002", "0007", "0009", "0037", "0060", "0088", "0096", "0130", "0151",
    "0183", "0184", "0190", "0191", "0192", "0193", "0195", "0196", "0198",
    "0201", "0204", "0208", "0209", "0210", "0211", "0212", "0213", "0216",
    "0221", "0230", "0235", "0240",
    "9910", "9913", "9914", "9915", "9918", "9919",
    "9920", "9922", "9923", "9924", "9925", "9926", "9927", "9928", "9929",
    "9930", "9931", "9932", "9933", "9934", "9935", "9936", "9937", "9938",
    "9939", "9940", "9941", "9942", "9943", "9944", "9945", "9946", "9947",
    "9948", "9950", "9951", "9952", "9953", "9955", "9956", "9957", "9958",
    "EM",
})


def normalize_scheme(value: Any) -> str | None:
    """Uppercase and trim an EAS scheme. Empty or non-text becomes None."""
    if not isinstance(value, str):
        return None
    compact = value.strip().upper()
    return compact or None


def normalize_endpoint_id(value: Any) -> str | None:
    """Trim an electronic address. Empty or non-text becomes None."""
    if not isinstance(value, str):
        return None
    stripped = value.strip()
    return stripped or None


def looks_like_known_scheme(value: Any) -> bool:
    """True when the value is a published Peppol EAS code we accept."""
    scheme = normalize_scheme(value)
    return scheme is not None and scheme in _KNOWN_SCHEMES


def inspect_party_endpoint(party: dict[str, Any], party_name: str) -> list[dict[str, str]]:
    """Return INV-039 / INV-040 / INV-041 observations for one party."""
    if "endpoint" not in party:
        return []
    endpoint = party.get("endpoint")
    if endpoint in (None, ""):
        return []
    path = f"/{party_name}/endpoint"
    if not isinstance(endpoint, dict):
        return [_finding(
            "INV-039",
            f"{party_name.title()} electronic address is not an object with scheme and id.",
            f"Use {party_name}.endpoint.scheme (EAS code) and {party_name}.endpoint.id, or omit endpoint.",
            path,
        )]

    findings: list[dict[str, str]] = []
    scheme = normalize_scheme(endpoint.get("scheme"))
    identifier = normalize_endpoint_id(endpoint.get("id"))
    if scheme is None or scheme not in _KNOWN_SCHEMES:
        findings.append(_finding(
            "INV-039",
            f"{party_name.title()} electronic-address scheme is missing or not a published EAS code.",
            "Use a Peppol EAS scheme such as 0088 (GLN), 0192, 0208, or EM, or omit endpoint.",
            f"{path}/scheme",
        ))
    if identifier is None:
        findings.append(_finding(
            "INV-040",
            f"{party_name.title()} electronic address is empty or not text.",
            f"Provide {party_name}.endpoint.id as text, or omit endpoint.",
            f"{path}/id",
        ))
    if scheme in _KNOWN_SCHEMES and identifier is not None and not _scheme_id_ok(scheme, identifier):
        findings.append(_finding(
            "INV-041",
            f"{party_name.title()} electronic address does not match the published {scheme} shape.",
            f"Correct the {scheme} identifier. This is a format typo check, not a directory lookup.",
            f"{path}/id",
        ))
    return findings


def inspect_party_endpoints(invoice: dict[str, Any]) -> list[dict[str, str]]:
    """Return endpoint observations for supplier and customer when present."""
    if not isinstance(invoice, dict):
        return []
    findings: list[dict[str, str]] = []
    for party_name in ("supplier", "customer"):
        party = invoice.get(party_name)
        if isinstance(party, dict):
            findings.extend(inspect_party_endpoint(party, party_name))
    return findings


def _scheme_id_ok(scheme: str, identifier: str) -> bool:
    if scheme == "0088":
        return _gln_ok(identifier)
    if scheme == "EM":
        return _email_ok(identifier)
    if scheme == "0007":
        return _digits(identifier, 10)
    if scheme == "0184":
        return _digits(identifier, 8)
    if scheme == "0190":
        return _digits(identifier, 20)
    if scheme == "0192":
        return _digits(identifier, 9)
    if scheme == "0208":
        return _digits(identifier, 10)
    if scheme == "0212":
        compact = "".join(ch for ch in identifier if ch.isalnum())
        return len(compact) in {8, 9} and compact[:-1].isdigit()
    compact = "".join(ch for ch in identifier if ch.isalnum() or ch in "@.-_:/+")
    return bool(compact)


def _digits(identifier: str, length: int) -> bool:
    compact = "".join(ch for ch in identifier if ch.isdigit())
    return len(compact) == length


def _gln_ok(identifier: str) -> bool:
    digits = "".join(ch for ch in identifier if ch.isdigit())
    if len(digits) != 13:
        return False
    total = sum(int(digit) * (1 if index % 2 == 0 else 3) for index, digit in enumerate(digits[:12]))
    check = (10 - (total % 10)) % 10
    return check == int(digits[12])


def _email_ok(identifier: str) -> bool:
    if identifier != identifier.strip() or " " in identifier or identifier.count("@") != 1:
        return False
    local, domain = identifier.split("@")
    return bool(local) and "." in domain and not domain.startswith(".") and not domain.endswith(".")


def _finding(rule: str, message: str, fix: str, path: str) -> dict[str, str]:
    return {"rule": rule, "message": message, "fix": fix, "path": path}

src/einvoice_preflight/facturx.py.text:
"""Unwrap the e-invoice XML inside a Factur-X / ZUGFeRD / XRechnung PDF.

The PDF is a transport envelope. The invoice is the embedded file named
``factur-x.xml``, ``zugferd-invoice.xml``, or ``xrechnung.xml``. This module
finds that attachment and returns its bytes so ``formats.parse_bytes`` can
run the same UBL/CII checks as a bare XML drop.

It is not a PDF renderer, a signature verifier, or a Factur-X profile
validator. Encrypted PDFs are refused. External file specifications are
ignored — only bytes already in this file are read.
"""

from __future__ import annotations

import re
import zlib
from typing import Iterable


class EmbeddedInvoiceError(Exception):
    """The PDF could not be unwrapped into invoice XML."""


PREFERRED_NAMES = (
    "factur-x.xml",
    "zugferd-invoice.xml",
    "xrechnung.xml",
)

_NAME_RE = re.compile(rb"/F\s*\(([^)]+)\)")
_TYPE_EMBEDDED = re.compile(rb"/Type\s*/EmbeddedFile\b")
_FILTER_FLATE = re.compile(rb"/Filter\s*(?:/FlateDecode|\[\s*/FlateDecode\s*\])")
_LENGTH_RE = re.compile(rb"/Length\s+(\d+)")


def looks_like_pdf(data: bytes) -> bool:
    """True when the leading bytes are a PDF header, ignoring a UTF-8 BOM."""
    return data.lstrip(b"\xef\xbb\xbf \t\r\n").startswith(b"%PDF-")


def safe_attachment_label(name: str) -> str:
    """Return a known Factur-X attachment name, or a generic label.

    Arbitrary PDF attachment names are attacker-controlled. Only the three
    standard invoice filenames are echoed back to the operator.
    """
    key = (name or "").strip().lower()
    return key if key in PREFERRED_NAMES else "embedded invoice XML"


def envelope_note(label: str, syntax: str) -> str:
    """One-line confirmation that a PDF envelope was opened."""
    return f"Unwrapped {label} ({syntax.upper()}) from the PDF."


def extract_embedded_invoice(data: bytes) -> tuple[bytes, str]:
    """Return ``(xml_bytes, safe_attachment_label)`` from a Factur-X-style PDF."""
    if not looks_like_pdf(data):
        raise EmbeddedInvoiceError("The file is not a PDF.")
    if _is_encrypted(data):
        raise EmbeddedInvoiceError(
            "This PDF is encrypted. Export the Factur-X file without a password "
            "or drop the embedded XML itself."
        )
    attachments = list(_embedded_files(data))
    if not attachments:
        raise EmbeddedInvoiceError(
            "This PDF has no embedded invoice file. Factur-X, ZUGFeRD, and "
            "XRechnung PDFs carry factur-x.xml, zugferd-invoice.xml, or "
            "xrechnung.xml as an attachment. A scanned paper PDF is not an "
            "e-invoice."
        )
    chosen = _prefer_invoice_attachment(attachments)
    if chosen is None:
        raise EmbeddedInvoiceError(
            "This PDF has embedded files, but none of them is UBL or "
            "CrossIndustryInvoice XML."
        )
    payload, name = chosen
    return payload, safe_attachment_label(name)


def extract_embedded_invoice_xml(data: bytes) -> bytes:
    """Return the embedded invoice XML bytes from a Factur-X-style PDF.

    Raises ``EmbeddedInvoiceError`` when the file is not a readable unencrypted
    PDF with an invoice XML attachment.
    """
    payload, _label = extract_embedded_invoice(data)
    return payload


def build_pdf_with_attachment(
    payload: bytes,
    filename: str = "factur-x.xml",
    *,
    flate: bool = False,
    encrypt: bool = False,
) -> bytes:
    """Build a minimal PDF 1.4 that carries ``payload`` as an embedded file.

    Used by tests and to ship ``examples/factur-x-invoice.pdf``. Not a
    general-purpose writer.
    """
    data = zlib.compress(payload) if flate else payload
    filter_line = "\n/Filter /FlateDecode" if flate else ""
    fname = (
        filename.replace("\\", "\\\\")
        .replace("(", "\\(")
        .replace(")", "\\)")
    )
    out = bytearray(b"%PDF-1.4\n%\xe2\xe3\xcf\xd3\n")
    offsets = [0]

    def add_object(number: int, body: bytes) -> None:
        while len(offsets) <= number:
            offsets.append(0)
        offsets[number] = len(out)
        out.extend(f"{number} 0 obj\n".encode("ascii"))
        out.extend(body)
        if not body.endswith(b"\n"):
            out.extend(b"\n")
        out.extend(b"endobj\n")

    add_object(
        1,
        (
            f"<< /Type /Catalog /Pages 2 0 R /Names << /EmbeddedFiles 3 0 R >> "
            f"/AF [4 0 R] >>"
        ).encode("ascii"),
    )
    add_object(2, b"<< /Type /Pages /Kids [] /Count 0 >>")
    add_object(3, f"<< /Names [({fname}) 4 0 R] >>".encode("ascii"))
    add_object(
        4,
        (
            f"<< /Type /Filespec /F ({fname}) /UF ({fname}) "
            f"/EF << /F 5 0 R >> /AFRelationship /Data >>"
        ).encode("ascii"),
    )
    stream = (
        f"<< /Type /EmbeddedFile /Subtype /text#2Fxml /Length {len(data)}"
        f"{filter_line} >>\nstream\n"
    ).encode("ascii") + data + b"\nendstream"
    add_object(5, stream)

    xref_at = len(out)
    out.extend(f"xref\n0 {len(offsets)}\n".encode("ascii"))
    out.extend(b"0000000000 65535 f \n")
    for number in range(1, len(offsets)):
        out.extend(f"{offsets[number]:010d} 00000 n \n".encode("ascii"))
    # A real encrypt dict is not required: refusal only looks at the trailer.
    encrypt_ref = " /Encrypt 6 0 R" if encrypt else ""
    out.extend(
        (
            f"trailer\n<< /Size {len(offsets)} /Root 1 0 R{encrypt_ref} >>\n"
            f"startxref\n{xref_at}\n%%EOF\n"
        ).encode("ascii")
    )
    return bytes(out)


def _is_encrypted(data: bytes) -> bool:
    trailer = data[data.rfind(b"trailer") :] if b"trailer" in data else data[-2048:]
    return b"/Encrypt" in trailer


def _embedded_files(data: bytes) -> Iterable[tuple[str, bytes]]:
    for match in _TYPE_EMBEDDED.finditer(data):
        start = data.rfind(b"obj", 0, match.start())
        if start == -1:
            continue
        # Walk back to the object header so /F (name) on a Filespec nearby
        # can still be found; the name usually lives on the previous object.
        window_start = max(0, start - 512)
        window = data[window_start : match.start() + 800]
        name = _attachment_name(window)
        stream = _read_stream_after(data, match.start())
        if stream is None:
            continue
        yield name, stream


def _attachment_name(window: bytes) -> str:
    names = _NAME_RE.findall(window)
    if not names:
        return ""
    raw = names[-1].replace(br"\(", b"(").replace(br"\)", b")").replace(br"\\", b"\\")
    return raw.decode("latin-1", errors="replace").strip()


def _read_stream_after(data: bytes, type_at: int) -> bytes | None:
    stream_at = data.find(b"stream", type_at)
    if stream_at == -1 or stream_at - type_at > 1024:
        return None
    header = data[type_at:stream_at]
    after = stream_at + len(b"stream")
    if after < len(data) and data[after : after + 2] == b"\r\n":
        after += 2
    elif after < len(data) and data[after : after + 1] in (b"\n", b"\r"):
        after += 1
    length_match = _LENGTH_RE.search(header)
    if length_match:
        length = int(length_match.group(1))
        payload = data[after : after + length]
    else:
        end = data.find(b"endstream", after)
        if end == -1:
            return None
        payload = data[after:end]
        if payload.endswith(b"\r\n"):
            payload = payload[:-2]
        elif payload.endswith(b"\n") or payload.endswith(b"\r"):
            payload = payload[:-1]
    if _FILTER_FLATE.search(header):
        try:
            return zlib.decompress(payload)
        except zlib.error as exc:
            raise EmbeddedInvoiceError(
                "The embedded invoice stream is compressed in a way this tool "
                "cannot read. Export the XML from the PDF or drop the XML file."
            ) from exc
    return payload


def _prefer_invoice_attachment(
    attachments: list[tuple[str, bytes]],
) -> tuple[bytes, str] | None:
    by_name = {name.lower(): payload for name, payload in attachments}
    for preferred in PREFERRED_NAMES:
        payload = by_name.get(preferred)
        if payload is not None and _looks_like_invoice_xml(payload):
            return payload, preferred
    for name, payload in attachments:
        if _looks_like_invoice_xml(payload):
            return payload, name
    return None


def _looks_like_invoice_xml(data: bytes) -> bool:
    head = data.lstrip()[:4096]
    return (
        b"urn:oasis:names:specification:ubl:schema:xsd:Invoice-2" in head
        or b"urn:oasis:names:specification:ubl:schema:xsd:CreditNote-2" in head
        or b"CrossIndustryInvoice" in head
    )

src/einvoice_preflight/iban.py.text:
"""Offline IBAN shape and checksum observations.

This is a typo catch for payment instructions, not a bank lookup and not a
determination that an account exists, belongs to the named party, or may
receive funds. Short internal account numbers are left alone.
"""

from __future__ import annotations

from typing import Any


# Published IBAN lengths (ISO 13616 / SWIFT registry). A matching country
# with the wrong length is a format observation; unknown countries still
# get the universal MOD-97 check when the compact value looks complete.
_LENGTHS = {
    "AD": 24, "AE": 23, "AL": 28, "AT": 20, "AZ": 28, "BA": 20, "BE": 16,
    "BG": 22, "BH": 22, "BR": 29, "BY": 28, "CH": 21, "CR": 22, "CY": 28,
    "CZ": 24, "DE": 22, "DK": 18, "DO": 28, "EE": 20, "EG": 29, "ES": 24,
    "FI": 18, "FO": 18, "FR": 27, "GB": 22, "GE": 22, "GI": 23, "GL": 18,
    "GR": 27, "GT": 28, "HR": 21, "HU": 28, "IE": 22, "IL": 23, "IQ": 23,
    "IS": 26, "IT": 27, "JO": 30, "KW": 30, "KZ": 20, "LB": 28, "LC": 32,
    "LI": 21, "LT": 20, "LU": 20, "LV": 21, "LY": 25, "MC": 27, "MD": 24,
    "ME": 22, "MK": 19, "MR": 27, "MT": 31, "MU": 30, "NL": 18, "NO": 15,
    "PK": 24, "PL": 28, "PS": 29, "PT": 25, "QA": 29, "RO": 24, "RS": 22,
    "SA": 24, "SE": 24, "SI": 19, "SK": 24, "SM": 27, "TN": 24, "TR": 26,
    "UA": 29, "VA": 22, "VG": 24, "XK": 20,
}


def normalize_iban(value: Any) -> str | None:
    """Uppercase and strip separators. Empty or non-text becomes None."""
    if not isinstance(value, str):
        return None
    compact = "".join(ch for ch in value.upper() if ch.isalnum())
    return compact or None


def looks_like_complete_iban(value: Any) -> bool:
    """True when the value is a country-prefixed IBAN, right length or not.

    "checksum" is a known-length (or unknown-country) shape ready for the
    mod-97 check; "bad-format" is a known country whose length is wrong.
    Both are IBAN-shaped enough for the cross-field checks that gate on this
    (BIC country match, remittance-missing, payment-means-needs-IBAN) --
    only "unknown" (no country-shaped prefix at all, e.g. an internal
    account id) should read as "there is no IBAN here". This used to check
    for a _classify() result of "format", which _classify() never returns,
    so every wrong-length IBAN silently read as "not an IBAN" and skipped
    those checks instead of surfacing them alongside the length finding.
    """
    compact = normalize_iban(value)
    if compact is None:
        return False
    return _classify(compact) in {"checksum", "bad-format"}


def inspect_payment_iban(invoice: dict[str, Any]) -> list[dict[str, str]]:
    """Return INV-024 / INV-025 observations for an optional payment IBAN."""
    payment = invoice.get("payment")
    if not isinstance(payment, dict):
        return []
    iban = payment.get("iban")
    if iban in (None, ""):
        return []
    return _check_explicit(iban, "/payment/iban")


def _check_explicit(value: Any, path: str) -> list[dict[str, str]]:
    if not isinstance(value, str) or not value.strip():
        return [_finding(
            "INV-024",
            "Payment IBAN is empty or not text.",
            "Provide the IBAN as text, or omit payment.iban.",
            path,
        )]
    compact = normalize_iban(value)
    if compact is None:
        return [_finding(
            "INV-024",
            "Payment IBAN is empty or not text.",
            "Provide the IBAN as text, or omit payment.iban.",
            path,
        )]
    kind = _classify(compact)
    if kind == "unknown":
        return [_finding(
            "INV-024",
            "Payment IBAN is not a country-prefixed account number.",
            "Use a two-letter country prefix, two check digits, and the national account number, or omit payment.iban.",
            path,
        )]
    if kind == "bad-format":
        country = compact[:2]
        return [_finding(
            "INV-024",
            f"Payment IBAN does not match the published {country} length.",
            f"Correct the {country} IBAN length and characters, or omit payment.iban for an internal account id.",
            path,
        )]
    if kind == "checksum" and not _mod97_ok(compact):
        country = compact[:2]
        return [_finding(
            "INV-025",
            f"Payment IBAN fails the published {country} checksum.",
            f"Correct the {country} IBAN digits. This is a checksum typo check, not a bank lookup.",
            path,
        )]
    return []


def _classify(compact: str) -> str:
    if len(compact) < 15 or len(compact) > 34:
        return "unknown"
    country, check, bban = compact[:2], compact[2:4], compact[4:]
    if not country.isalpha() or not check.isdigit() or not bban.isalnum():
        return "unknown"
    expected = _LENGTHS.get(country)
    if expected is None:
        return "checksum"
    if len(compact) != expected:
        return "bad-format"
    return "checksum"


def _mod97_ok(compact: str) -> bool:
    rearranged = compact[4:] + compact[:4]
    numeric = "".join(str(int(char, 36)) for char in rearranged)
    return int(numeric) % 97 == 1


def _finding(rule: str, message: str, fix: str, path: str) -> dict[str, str]:
    return {"rule": rule, "message": message, "fix": fix, "path": path}

src/einvoice_preflight/period.py.text:
"""Offline invoice-period (BT-73 / BT-74) observations.

A service invoice that names only one end of the billing window, or that
ends before it starts, is a common ERP export mistake. Networks then
reject the file after the bookkeeper already sent it. This is a
date-shape check, not a Peppol profile determination and not a claim
that the dates match the underlying contract. Findings never repeat the
dates.
"""

from __future__ import annotations

from datetime import date
from typing import Any


def parse_iso_date(value: Any) -> date | None:
    """Accept the documented extended YYYY-MM-DD form only."""
    if not isinstance(value, str) or len(value) != 10 or value[4] != "-" or value[7] != "-":
        return None
    try:
        return date.fromisoformat(value)
    except ValueError:
        return None


def inspect_invoice_period(invoice: dict[str, Any]) -> list[dict[str, str]]:
    """Return INV-042 / INV-043 observations for an optional invoice period."""
    if "period" not in invoice:
        return []
    period = invoice.get("period")
    if period in (None, ""):
        return []
    if not isinstance(period, dict):
        return [_finding(
            "INV-042",
            "Invoice period is not an object with start and end dates.",
            "Use period.start and period.end as YYYY-MM-DD, or omit period.",
            "/period",
        )]

    start_raw = period.get("start")
    end_raw = period.get("end")
    start_missing = start_raw in (None, "")
    end_missing = end_raw in (None, "")
    if start_missing and end_missing:
        return [_finding(
            "INV-042",
            "Invoice period is missing both start and end dates.",
            "Add period.start and period.end as YYYY-MM-DD, or omit period.",
            "/period",
        )]

    findings: list[dict[str, str]] = []
    start = None if start_missing else parse_iso_date(start_raw)
    end = None if end_missing else parse_iso_date(end_raw)
    if start_missing:
        findings.append(_finding(
            "INV-042",
            "Invoice period is missing a start date.",
            "Add period.start as YYYY-MM-DD, or omit period.",
            "/period/start",
        ))
    elif start is None:
        findings.append(_finding(
            "INV-042",
            "Invoice period start is not an ISO date.",
            "Use YYYY-MM-DD, for example 2026-07-01.",
            "/period/start",
        ))
    if end_missing:
        findings.append(_finding(
            "INV-042",
            "Invoice period is missing an end date.",
            "Add period.end as YYYY-MM-DD, or omit period.",
            "/period/end",
        ))
    elif end is None:
        findings.append(_finding(
            "INV-042",
            "Invoice period end is not an ISO date.",
            "Use YYYY-MM-DD, for example 2026-07-31.",
            "/period/end",
        ))
    if start is not None and end is not None and end < start:
        findings.append(_finding(
            "INV-043",
            "Invoice period end is earlier than the start.",
            "Set period.end to period.start or a later date.",
            "/period/end",
        ))
    return findings


def _finding(rule: str, message: str, fix: str, path: str) -> dict[str, str]:
    return {"rule": rule, "message": message, "fix": fix, "path": path}

src/einvoice_preflight/reference.py.text:
"""Offline buyer / purchase-order reference (BT-10 / BT-13) observations.

A placeholder PO, an empty buyer reference, or a purchase-order field that
repeats the invoice number is a common ERP export mistake. Accounts-payable
systems then bounce the file after the bookkeeper already sent it. This is
a shape and consistency check, not a Peppol profile determination and not
a claim that the buyer issued that order. Findings never repeat the
reference.
"""

from __future__ import annotations

from typing import Any

# Published CIUS text fields often cap buyer/order references at 70.
_MAX_LENGTH = 70

# Values that pass schema but never match a real purchase order.
_PLACEHOLDERS = {"na", "none", "null", "tbd", "todo", "unknown", "-", "--", "..."}


def normalize_reference(value: Any) -> str | None:
    """Strip surrounding space. Empty or non-text becomes None."""
    if not isinstance(value, str):
        return None
    stripped = value.strip()
    return stripped or None


def looks_like_placeholder(value: Any) -> bool:
    """True when the value is a documented empty-token placeholder."""
    compact = normalize_reference(value)
    if compact is None:
        return False
    token = "".join(ch for ch in compact.lower() if ch.isalnum() or ch in "-.")
    if token in _PLACEHOLDERS:
        return True
    letters = "".join(ch for ch in compact.lower() if ch.isalnum())
    return letters in _PLACEHOLDERS


def inspect_commercial_references(invoice: dict[str, Any]) -> list[dict[str, str]]:
    """Return INV-047 / INV-048 / INV-049 observations for optional refs."""
    findings: list[dict[str, str]] = []
    if "buyer_reference" in invoice:
        findings.extend(_check_explicit(
            invoice.get("buyer_reference"),
            "INV-047",
            "/buyer_reference",
            "Buyer reference",
            "Add buyer_reference as the cost-center or buyer text, or omit buyer_reference.",
        ))
    if "order_reference" in invoice:
        order_findings = _check_explicit(
            invoice.get("order_reference"),
            "INV-048",
            "/order_reference",
            "Purchase-order reference",
            "Add order_reference as the buyer purchase-order number, or omit order_reference.",
        )
        findings.extend(order_findings)
        if not order_findings and _same_reference(
            invoice.get("order_reference"),
            invoice.get("invoice_number"),
        ):
            findings.append(_finding(
                "INV-049",
                "Purchase-order reference repeats the invoice number.",
                "Set order_reference to the buyer purchase-order number, or omit order_reference.",
                "/order_reference",
            ))
    return findings


def _check_explicit(value: Any, rule: str, path: str, label: str, omit_fix: str) -> list[dict[str, str]]:
    if not isinstance(value, str) or not value.strip():
        return [_finding(
            rule,
            f"{label} is empty or not text.",
            omit_fix,
            path,
        )]
    stripped = value.strip()
    if len(stripped) > _MAX_LENGTH:
        return [_finding(
            rule,
            f"{label} is longer than the usual 70-character network field.",
            f"Shorten the {label.lower()} so a receiving system can store it, or omit the field.",
            path,
        )]
    if looks_like_placeholder(value):
        return [_finding(
            rule,
            f"{label} is a placeholder, not a buyer or purchase-order number.",
            omit_fix,
            path,
        )]
    return []


def _same_reference(left: Any, right: Any) -> bool:
    first = normalize_reference(left)
    second = normalize_reference(right)
    if first is None or second is None:
        return False
    return first.casefold() == second.casefold()


def _finding(rule: str, message: str, fix: str, path: str) -> dict[str, str]:
    return {"rule": rule, "message": message, "fix": fix, "path": path}

src/einvoice_preflight/remittance.py.text:
"""Offline remittance / payment-reference observations.

When a complete IBAN is present, a remittance reference is what the buyer
puts on the transfer so the seller can match the payment. Structured RF
values (ISO 11649) get a MOD-97 typo catch. This is not a bank lookup and
not a determination that a payment will be allocated. Findings never repeat
the reference.
"""

from __future__ import annotations

from typing import Any

from .iban import looks_like_complete_iban


# SEPA unstructured remittance information is limited to 140 characters.
_UNSTRUCTURED_MAX = 140


def normalize_remittance(value: Any) -> str | None:
    """Uppercase and strip separators. Empty or non-text becomes None."""
    if not isinstance(value, str):
        return None
    compact = "".join(ch for ch in value.upper() if ch.isalnum())
    return compact or None


def looks_like_structured_rf(value: Any) -> bool:
    """True when the value is an ISO 11649 RF creditor reference shape."""
    compact = normalize_remittance(value)
    return compact is not None and _classify_rf(compact) in {"ok", "checksum"}


def inspect_payment_remittance(invoice: dict[str, Any]) -> list[dict[str, str]]:
    """Return INV-030 / INV-031 observations for an optional remittance."""
    payment = invoice.get("payment")
    if not isinstance(payment, dict):
        return []
    remittance = payment.get("remittance")
    missing = remittance in (None, "") or (isinstance(remittance, str) and not remittance.strip())
    if missing:
        if looks_like_complete_iban(payment.get("iban")):
            return [_finding(
                "INV-030",
                "Payment remittance reference is missing on an invoice that already names an IBAN.",
                "Add payment.remittance so the buyer can quote it on the transfer, or omit payment.iban.",
                "/payment/remittance",
            )]
        return []
    return _check_explicit(remittance, "/payment/remittance")


def _check_explicit(value: Any, path: str) -> list[dict[str, str]]:
    if not isinstance(value, str) or not value.strip():
        return [_finding(
            "INV-031",
            "Payment remittance reference is empty or not text.",
            "Provide the remittance as text, or omit payment.remittance.",
            path,
        )]
    stripped = value.strip()
    if len(stripped) > _UNSTRUCTURED_MAX:
        return [_finding(
            "INV-031",
            "Payment remittance reference is longer than the usual 140-character transfer note.",
            "Shorten the remittance so a bank transfer can carry it, or omit payment.remittance.",
            path,
        )]
    compact = normalize_remittance(value)
    if compact is None:
        return [_finding(
            "INV-031",
            "Payment remittance reference is empty or not text.",
            "Provide the remittance as text, or omit payment.remittance.",
            path,
        )]
    if not compact.startswith("RF"):
        return []
    kind = _classify_rf(compact)
    if kind == "unknown":
        return [_finding(
            "INV-031",
            "Payment remittance reference is not a structured RF creditor reference.",
            "Use RF, two check digits, and up to 21 characters, or an unstructured note that does not start with RF.",
            path,
        )]
    if kind == "checksum" and not _mod97_ok(compact):
        return [_finding(
            "INV-031",
            "Payment remittance reference fails the published RF checksum.",
            "Correct the RF check digits. This is a checksum typo check, not a bank lookup.",
            path,
        )]
    return []


def _classify_rf(compact: str) -> str:
    # ISO 11649: RF + 2 digits + 1 to 21 alphanumeric characters.
    if not compact.startswith("RF") or len(compact) < 5 or len(compact) > 25:
        return "unknown"
    check, body = compact[2:4], compact[4:]
    if not check.isdigit() or not body.isalnum():
        return "unknown"
    return "checksum"


def _mod97_ok(compact: str) -> bool:
    rearranged = compact[4:] + compact[:4]
    numeric = "".join(str(int(char, 36)) for char in rearranged)
    return int(numeric) % 97 == 1


def _finding(rule: str, message: str, fix: str, path: str) -> dict[str, str]:
    return {"rule": rule, "message": message, "fix": fix, "path": path}

