from __future__ import annotations

from decimal import Decimal
from xml.etree import ElementTree
from typing import Any


def _children(element: ElementTree.Element, name: str) -> list[ElementTree.Element]:
    return [child for child in element.iter() if child.tag.rsplit("}", 1)[-1] == name]


def _text(element: ElementTree.Element, name: str, required: bool = True) -> str:
    matches = _children(element, name)
    value = matches[0].text.strip() if matches and matches[0].text else ""
    if required and not value:
        raise ValueError(f"UBL field {name} is missing")
    return value


def _number(value: str) -> int | float:
    number = Decimal(value)
    return int(number) if number == number.to_integral_value() else float(number)


def _nested_text(element: ElementTree.Element, container: str, field: str) -> str:
    """Text of ``<container><field>``, scoped to that container.

    ``_children`` walks every descendant, so an unscoped lookup for ``ID`` on a
    party answers with whatever ``ID`` comes first in document order -- which on
    a party carrying ``cac:PartyTaxScheme`` is ``cac:TaxScheme/cbc:ID``, the
    name of the tax scheme ("VAT"). Scoping the search to the container first
    keeps a party identifier from being read out of an unrelated element.
    """
    for child in _children(element, container):
        value = _text(child, field, required=False)
        if value:
            return value
    return ""


def _party_identifier(party: ElementTree.Element) -> str:
    """The party's own identifier, in the order a receiver would resolve it.

    EN 16931 makes the seller and buyer identifiers (BT-29/BT-46) optional --
    plenty of real Peppol invoices identify a party by its electronic address
    and name alone. Treating the identifier as mandatory made those invoices
    unreadable rather than reporting a finding, so this returns "" and lets the
    checks decide what a missing identifier means.
    """
    return (
        _nested_text(party, "PartyIdentification", "ID")
        or _text(party, "EndpointID", required=False)
        or _nested_text(party, "PartyLegalEntity", "CompanyID")
        or _nested_text(party, "PartyTaxScheme", "CompanyID")
    )


def _party(element: ElementTree.Element) -> dict[str, Any]:
    party = next(iter(_children(element, "Party")), element)
    identifier = _party_identifier(party)
    # XRechnung carries the legal name in PartyLegalEntity/RegistrationName and
    # may omit PartyName entirely, so that is a source for the name, not a
    # reason to refuse the document.
    name = _nested_text(party, "PartyName", "Name") or _nested_text(
        party, "PartyLegalEntity", "RegistrationName"
    ) or _text(party, "Name")
    mapped: dict[str, Any] = {"id": identifier, "name": name}
    vat_id = ""
    for scheme in _children(party, "PartyTaxScheme"):
        # A national tax number uses TaxScheme/ID "FC"; only VAT (or an
        # unlabelled scheme) is a VAT ID.
        scheme_id = _nested_text(scheme, "TaxScheme", "ID").upper()
        if scheme_id and scheme_id != "VAT":
            continue
        vat_id = _text(scheme, "CompanyID", required=False)
        if vat_id:
            break
    if vat_id:
        mapped["vat_id"] = vat_id
    endpoint = _endpoint(party)
    if endpoint:
        mapped["endpoint"] = endpoint
    return mapped


def _endpoint(party: ElementTree.Element) -> dict[str, str] | None:
    """Map Party/EndpointID and its schemeID when either is present."""
    for child in party.iter():
        if child.tag.rsplit("}", 1)[-1] != "EndpointID":
            continue
        value = (child.text or "").strip()
        scheme = ""
        for key, attr in child.attrib.items():
            if key.rsplit("}", 1)[-1] == "schemeID":
                scheme = (attr or "").strip()
        if value or scheme:
            return {"id": value, "scheme": scheme}
    return None


_DOCUMENT_ROOTS = {
    "Invoice": ("invoice", "InvoiceLine", "InvoicedQuantity"),
    "CreditNote": ("credit_note", "CreditNoteLine", "CreditedQuantity"),
    "DebitNote": ("debit_note", "DebitNoteLine", "DebitedQuantity"),
}


def parse_ubl_invoice(source: bytes | str) -> dict[str, Any]:
    """Map a local UBL Invoice, CreditNote, or DebitNote into the checker shape."""
    raw = source.encode() if isinstance(source, str) else source
    if b"<!DOCTYPE" in raw.upper() or b"<!ENTITY" in raw.upper():
        raise ValueError("DTD and entity declarations are not supported")
    try:
        root = ElementTree.fromstring(raw)
    except ElementTree.ParseError as exc:
        raise ValueError(str(exc)) from exc
    root_name = root.tag.rsplit("}", 1)[-1]
    if root_name not in _DOCUMENT_ROOTS:
        raise ValueError("UBL document root must be Invoice, CreditNote, or DebitNote")
    document_type, line_name, quantity_name = _DOCUMENT_ROOTS[root_name]

    lines = []
    for line in _children(root, line_name):
        quantity = _text(line, quantity_name)
        price = _text(line, "PriceAmount")
        net = _text(line, "LineExtensionAmount")
        category = next(iter(_children(line, "ClassifiedTaxCategory")), line)
        mapped_line = {
            "description": _text(line, "Name"),
            "quantity": _number(quantity),
            "unit_price": _number(price),
            "tax_percent": _number(_text(category, "Percent")),
            "net": _number(net),
        }
        mapped_line.update(_tax_category_fields(category))
        lines.append(mapped_line)

    supplier = next(iter(_children(root, "AccountingSupplierParty")), root)
    customer = next(iter(_children(root, "AccountingCustomerParty")), root)
    total = next(iter(_children(root, "LegalMonetaryTotal")), root)
    tax_totals = _children(root, "TaxTotal")
    if not tax_totals:
        raise ValueError("UBL field TaxAmount is missing")
    tax_total = sum((Decimal(_text(item, "TaxAmount")) for item in tax_totals), Decimal("0"))
    due_date = _text(root, "DueDate", required=False)
    type_code = (
        _text(root, "InvoiceTypeCode", required=False)
        or _text(root, "CreditNoteTypeCode", required=False)
        or _text(root, "DebitNoteTypeCode", required=False)
    )
    original = _billing_reference(root)
    invoice = {
        "invoice_number": _text(root, "ID"),
        "issue_date": _text(root, "IssueDate"),
        **({"due_date": due_date} if due_date else {}),
        "document_type": document_type,
        **({"document_code": type_code} if type_code else {}),
        **({"original_invoice": original} if original else {}),
        "currency": _text(root, "DocumentCurrencyCode"),
        "supplier": _party(supplier),
        "customer": _party(customer),
        "lines": lines,
        "totals": {
            "net": _number(_text(total, "TaxExclusiveAmount")),
            # UBL permits a TaxTotal per tax scheme; the invoice tax is their sum.
            "tax": _number(str(tax_total)),
            "gross": _number(_text(total, "TaxInclusiveAmount")),
            **_optional_monetary_totals(total),
        },
    }
    payment = _payee_payment(root)
    terms_days = _payment_terms_days(root)
    if terms_days:
        if not payment:
            payment = {}
        payment["terms_days"] = terms_days
    if payment:
        invoice["payment"] = payment
    exemption = _document_exemption(root)
    if exemption:
        invoice.update(exemption)
    breakdown = _tax_breakdown(root)
    if breakdown:
        invoice["tax_breakdown"] = breakdown
    period = _invoice_period(root)
    if period:
        invoice["period"] = period
    invoice.update(_commercial_references(root))
    adjustments = _header_adjustments(root)
    if adjustments:
        invoice["adjustments"] = adjustments
    return invoice


def _tax_category_fields(category: ElementTree.Element) -> dict[str, str]:
    """Map ClassifiedTaxCategory ID and exemption reason / code when present."""
    extras: dict[str, str] = {}
    tax_id = ""
    for child in list(category):
        tag = child.tag.rsplit("}", 1)[-1]
        if tag == "ID":
            tax_id = (child.text or "").strip()
    if tax_id:
        extras["tax_category"] = tax_id
    reason = _text(category, "TaxExemptionReason", required=False)
    if reason:
        extras["tax_reason"] = reason
    reason_code = _text(category, "TaxExemptionReasonCode", required=False)
    if reason_code:
        extras["tax_reason_code"] = reason_code
    return extras


def _tax_breakdown(root: ElementTree.Element) -> list[dict[str, Any]]:
    """Map TaxTotal/TaxSubtotal rows into tax_breakdown."""
    rows: list[dict[str, Any]] = []
    for subtotal in _children(root, "TaxSubtotal"):
        taxable = _text(subtotal, "TaxableAmount", required=False)
        tax = _text(subtotal, "TaxAmount", required=False)
        category = next(iter(_children(subtotal, "TaxCategory")), None)
        percent = _text(category, "Percent", required=False) if category is not None else ""
        tax_id = ""
        if category is not None:
            for child in list(category):
                if child.tag.rsplit("}", 1)[-1] == "ID":
                    tax_id = (child.text or "").strip()
        if not taxable and not tax and not percent:
            continue
        row: dict[str, Any] = {}
        if percent:
            row["tax_percent"] = _number(percent)
        if taxable:
            row["taxable"] = _number(taxable)
        if tax:
            row["tax"] = _number(tax)
        if tax_id:
            row["tax_category"] = tax_id
        if row:
            rows.append(row)
    return rows


def _document_exemption(root: ElementTree.Element) -> dict[str, str]:
    """Map TaxSubtotal/TaxCategory exemption reason when present."""
    extras: dict[str, str] = {}
    for subtotal in _children(root, "TaxSubtotal"):
        for category in _children(subtotal, "TaxCategory"):
            reason = _text(category, "TaxExemptionReason", required=False)
            if reason and "tax_exemption_reason" not in extras:
                extras["tax_exemption_reason"] = reason
            reason_code = _text(category, "TaxExemptionReasonCode", required=False)
            if reason_code and "tax_exemption_reason_code" not in extras:
                extras["tax_exemption_reason_code"] = reason_code
    return extras


def _header_adjustments(root: ElementTree.Element) -> list[dict[str, Any]]:
    """Map invoice-level AllowanceCharge rows. Ignore line-level charges."""
    rows: list[dict[str, Any]] = []
    for child in list(root):
        if child.tag.rsplit("}", 1)[-1] != "AllowanceCharge":
            continue
        indicator = _text(child, "ChargeIndicator", required=False)
        amount = _text(child, "Amount", required=False)
        base = _text(child, "BaseAmount", required=False)
        percent = _text(child, "MultiplierFactorNumeric", required=False)
        reason = _text(child, "AllowanceChargeReason", required=False)
        reason_code = _text(child, "AllowanceChargeReasonCode", required=False)
        if not any((indicator, amount, base, percent, reason, reason_code)):
            continue
        row: dict[str, Any] = {}
        if indicator:
            row["kind"] = "charge" if indicator.strip().casefold() in {"true", "1"} else "allowance"
        if amount:
            row["amount"] = _number(amount)
        if base:
            row["base"] = _number(base)
        if percent:
            row["percent"] = _number(percent)
        if reason:
            row["reason"] = reason
        if reason_code:
            row["reason_code"] = reason_code
        if row:
            rows.append(row)
    return rows


def _commercial_references(root: ElementTree.Element) -> dict[str, str]:
    """Map invoice-level BuyerReference and OrderReference/ID when present."""
    extras: dict[str, str] = {}
    for child in list(root):
        tag = child.tag.rsplit("}", 1)[-1]
        if tag == "BuyerReference":
            extras["buyer_reference"] = (child.text or "").strip()
        elif tag == "OrderReference":
            extras["order_reference"] = _text(child, "ID", required=False)
    return extras


def _invoice_period(root: ElementTree.Element) -> dict[str, str] | None:
    """Map invoice-level InvoicePeriod StartDate/EndDate. Ignore line periods."""
    for child in list(root):
        if child.tag.rsplit("}", 1)[-1] != "InvoicePeriod":
            continue
        start = _text(child, "StartDate", required=False)
        end = _text(child, "EndDate", required=False)
        if start or end:
            period: dict[str, str] = {}
            if start:
                period["start"] = start
            if end:
                period["end"] = end
            return period
    return None


def _billing_reference(root: ElementTree.Element) -> str:
    """Map BillingReference/InvoiceDocumentReference/ID when present."""
    for ref in _children(root, "BillingReference"):
        for invoice_ref in _children(ref, "InvoiceDocumentReference"):
            value = _text(invoice_ref, "ID", required=False)
            if value:
                return value
    return ""


def _optional_monetary_totals(total: ElementTree.Element) -> dict[str, int | float]:
    """Map PrepaidAmount and PayableAmount when the UBL invoice includes them."""
    extras: dict[str, int | float] = {}
    prepaid = _text(total, "PrepaidAmount", required=False)
    if prepaid:
        extras["prepaid"] = _number(prepaid)
    payable = _text(total, "PayableAmount", required=False)
    if payable:
        extras["due"] = _number(payable)
    return extras


def _payment_terms_days(root: ElementTree.Element) -> str:
    """Map invoice-level PaymentTerms/SettlementPeriod/DurationMeasure in days."""
    for child in list(root):
        if child.tag.rsplit("}", 1)[-1] != "PaymentTerms":
            continue
        for period in _children(child, "SettlementPeriod"):
            for measure in list(period):
                if measure.tag.rsplit("}", 1)[-1] != "DurationMeasure":
                    continue
                unit = (measure.get("unitCode") or "").strip().upper()
                value = (measure.text or "").strip()
                if value and unit in {"DAY", "D"}:
                    return value
    return ""


def _payee_payment(root: ElementTree.Element) -> dict[str, str]:
    """Map payment means code, remittance, payee account, and branch BIC."""
    for means in _children(root, "PaymentMeans"):
        payment: dict[str, str] = {}
        code = _text(means, "PaymentMeansCode", required=False)
        if code:
            payment["means"] = code
        remittance = _payment_reference(means)
        if remittance:
            payment["remittance"] = remittance
        for account in _children(means, "PayeeFinancialAccount"):
            for child in list(account):
                tag = child.tag.rsplit("}", 1)[-1]
                if tag == "ID":
                    value = (child.text or "").strip()
                    if value:
                        payment["iban"] = value
                elif tag == "FinancialInstitutionBranch":
                    bic = _branch_bic(child)
                    if bic:
                        payment["bic"] = bic
        if payment:
            return payment
    return {}


def _payment_reference(means: ElementTree.Element) -> str:
    """Map PaymentID, then InstructionNote, as the remittance the buyer quotes."""
    for name in ("PaymentID", "InstructionNote"):
        for child in list(means):
            if child.tag.rsplit("}", 1)[-1] == name:
                value = (child.text or "").strip()
                if value:
                    return value
    return ""


def _branch_bic(branch: ElementTree.Element) -> str:
    """Accept branch/ID or branch/FinancialInstitution/ID."""
    for child in branch.iter():
        if child.tag.rsplit("}", 1)[-1] == "ID":
            value = (child.text or "").strip()
            if value:
                return value
    return ""

src/einvoice_preflight/vat.py.text:
"""Offline VAT identifier shape and checksum observations.

This is a typo catch, not a VIES lookup and not a determination that a party
is registered, in scope, or entitled to charge tax. Identifiers that do not
match a complete published national shape are treated as internal ERP codes
and are left alone.
"""

from __future__ import annotations

from typing import Any


# Countries we will checksum. Others with a 2-letter prefix are format-only
# when the body matches the published length, so a bookkeeper still gets a
# length observation without a false "valid" claim.
_FORMAT_ONLY = {
    "BG": (9, 10),
    "CY": (9,),
    "CZ": (8, 9, 10),
    "EE": (9,),
    "EL": (9,),
    "GR": (9,),
    "HR": (11,),
    "HU": (8,),
    "LT": (9, 12),
    "LV": (11,),
    "MT": (8,),
    "RO": range(2, 11),
    "SI": (8,),
    "SK": (10,),
    "XI": (9, 12),
}


def normalize_vat(value: Any) -> str | None:
    """Uppercase and strip separators. Empty or non-text becomes None."""
    if not isinstance(value, str):
        return None
    compact = "".join(ch for ch in value.upper() if ch.isalnum())
    return compact or None


def looks_like_complete_vat(value: Any) -> bool:
    """True when the value matches a known country prefix and body length."""
    compact = normalize_vat(value)
    if compact is None or len(compact) < 4:
        return False
    country, body = compact[:2], compact[2:]
    if not country.isalpha():
        return False
    return _classify(country, body) in {"checksum", "format"}


def inspect_party_vat(party: dict[str, Any], party_name: str) -> list[dict[str, str]]:
    """Return INV-022 / INV-023 observations for one supplier or customer."""
    findings: list[dict[str, str]] = []
    vat_id = party.get("vat_id")
    checked: set[str] = set()
    if vat_id not in (None, ""):
        findings.extend(_check_explicit(vat_id, f"/{party_name}/vat_id", party_name))
        compact = normalize_vat(vat_id)
        if compact:
            checked.add(compact)
    identifier = party.get("id")
    compact_id = normalize_vat(identifier)
    if compact_id and compact_id not in checked and looks_like_complete_vat(identifier):
        findings.extend(_check_complete(identifier, f"/{party_name}/id", party_name))
    return findings


def _check_explicit(value: Any, path: str, party_name: str) -> list[dict[str, str]]:
    if not isinstance(value, str) or not value.strip():
        return [_finding(
            "INV-022",
            f"{party_name.title()} VAT identifier is empty or not text.",
            "Provide the VAT identifier as text, or omit vat_id.",
            path,
        )]
    compact = normalize_vat(value)
    if compact is None or len(compact) < 4 or not compact[:2].isalpha():
        return [_finding(
            "INV-022",
            f"{party_name.title()} VAT identifier is not a country-prefixed VAT number.",
            "Use a two-letter country prefix plus the national number, for example DE and nine digits.",
            path,
        )]
    return _evaluate(compact[:2], compact[2:], path, party_name, require_known=True)


def _check_complete(value: Any, path: str, party_name: str) -> list[dict[str, str]]:
    compact = normalize_vat(value)
    if compact is None:
        return []
    return _evaluate(compact[:2], compact[2:], path, party_name, require_known=False)


def _evaluate(country: str, body: str, path: str, party_name: str, require_known: bool) -> list[dict[str, str]]:
    kind = _classify(country, body)
    if kind == "unknown":
        if require_known:
            return [_finding(
                "INV-022",
                f"{party_name.title()} VAT identifier uses an unrecognized country prefix.",
                "Use an EU, UK, or other published VAT country prefix, or omit vat_id for an internal id.",
                path,
            )]
        return []
    if kind == "bad-format":
        return [_finding(
            "INV-022",
            f"{party_name.title()} VAT identifier does not match the published {country} shape.",
            f"Correct the {country} VAT identifier length and characters, or use an internal id without a country prefix.",
            path,
        )]
    if kind == "checksum" and not _checksum_ok(country, body):
        return [_finding(
            "INV-023",
            f"{party_name.title()} VAT identifier fails the published {country} checksum.",
            f"Correct the {country} VAT identifier digits. This is a checksum typo check, not a registration lookup.",
            path,
        )]
    return []


def _classify(country: str, body: str) -> str:
    if country == "DE":
        return "checksum" if body.isdigit() and len(body) == 9 else "bad-format"
    if country == "FR":
        return "checksum" if len(body) == 11 and body[2:].isdigit() else "bad-format"
    if country == "BE":
        digits = body[1:] if body[:1] == "0" and len(body) == 11 else body
        return "checksum" if digits.isdigit() and len(digits) in (9, 10) else "bad-format"
    if country == "NL":
        return "checksum" if len(body) == 12 and body[9] == "B" and body[:9].isdigit() and body[10:].isdigit() else "bad-format"
    if country == "AT":
        return "checksum" if body.startswith("U") and len(body) == 9 and body[1:].isdigit() else "bad-format"
    if country == "IT":
        return "checksum" if body.isdigit() and len(body) == 11 else "bad-format"
    if country == "ES":
        return "checksum" if _es_shape(body) else "bad-format"
    if country == "PL":
        return "checksum" if body.isdigit() and len(body) == 10 else "bad-format"
    if country == "SE":
        return "checksum" if body.isdigit() and len(body) in (10, 12) else "bad-format"
    if country == "DK":
        return "checksum" if body.isdigit() and len(body) == 8 else "bad-format"
    if country == "FI":
        return "checksum" if body.isdigit() and len(body) == 8 else "bad-format"
    if country == "PT":
        return "checksum" if body.isdigit() and len(body) == 9 else "bad-format"
    if country == "LU":
        return "checksum" if body.isdigit() and len(body) == 8 else "bad-format"
    if country == "IE":
        return "checksum" if _ie_shape(body) else "bad-format"
    if country in {"GB", "UK"}:
        return "checksum" if body.isdigit() and len(body) in (9, 12) else "bad-format"
    lengths = _FORMAT_ONLY.get(country)
    if lengths is None:
        return "unknown"
    if body.isalnum() and len(body) in lengths:
        return "format"
    return "bad-format"


def _checksum_ok(country: str, body: str) -> bool:
    if country == "DE":
        return _de(body)
    if country == "FR":
        return _fr(body)
    if country == "BE":
        return _be(body)
    if country == "NL":
        return _nl(body)
    if country == "AT":
        return _at(body)
    if country == "IT":
        return _it(body)
    if country == "ES":
        return _es(body)
    if country == "PL":
        return _pl(body)
    if country == "SE":
        return _se(body)
    if country == "DK":
        return _dk(body)
    if country == "FI":
        return _fi(body)
    if country == "PT":
        return _pt(body)
    if country == "LU":
        return _lu(body)
    if country == "IE":
        return _ie(body)
    if country in {"GB", "UK"}:
        return _gb(body)
    return False


def _de(digits: str) -> bool:
    product = 10
    for char in digits[:8]:
        step = (int(char) + product) % 10
        if step == 0:
            step = 10
        product = (2 * step) % 11
    return (11 - product) % 10 == int(digits[8])


def _fr(body: str) -> bool:
    siren = body[2:]
    if not siren.isdigit():
        return False
    key = body[:2]
    if not key.isdigit():
        # Letter keys exist; this tool only checksums the numeric-key form.
        return True
    expected = (12 + 3 * (int(siren) % 97)) % 97
    return int(key) == expected


def _be(body: str) -> bool:
    digits = body[1:] if body.startswith("0") and len(body) == 11 else body
    if len(digits) == 9:
        digits = "0" + digits
    if len(digits) != 10 or not digits.isdigit():
        return False
    return (int(digits[:8]) % 97 + int(digits[8:])) % 97 == 0


def _nl(body: str) -> bool:
    # Elfproef (11-proof): weights 9..2 on the first eight digits, then the
    # ninth (check) digit at weight -1, not +1. range(9, 0, -1) gave every
    # digit including the last a positive weight, which fails real valid
    # Dutch VAT numbers (NL123456782B01, the standard example) and mis-scores
    # typo'd ones the same way.
    total = sum(int(digit) * weight for digit, weight in zip(body[:8], range(9, 1, -1)))
    total -= int(body[8])
    return total % 11 == 0


def _at(body: str) -> bool:
    digits = [int(char) for char in body[1:]]
    total = 0
    for index, digit in enumerate(digits[:7]):
        value = digit if index % 2 == 0 else digit * 2
        total += value if value < 10 else value - 9
    check = (10 - (total + 4) % 10) % 10
    return check == digits[7]


def _it(digits: str) -> bool:
    total = 0
    for index, char in enumerate(digits[:10]):
        value = int(char)
        if index % 2 == 1:
            value *= 2
            value = value // 10 + value % 10
        total += value
    return (10 - total % 10) % 10 == int(digits[10])


def _es_shape(body: str) -> bool:
    if len(body) != 9:
        return False
    if body[0].isdigit() and body[8].isalpha() and body[1:8].isdigit():
        return True
    if body[0].isalpha() and body[1:8].isdigit() and body[8].isalnum():
        return True
    return False


def _es(body: str) -> bool:
    letters = "TRWAGMYFPDXBNJZSQVHLCKE"
    if body[0].isdigit() and body[8].isalpha():
        return body[8] == letters[int(body[:8]) % 23]
    if not body[0].isalpha() or not body[1:8].isdigit():
        return False
    total = 0
    for index, char in enumerate(body[1:8]):
        value = int(char) * (2 if index % 2 == 0 else 1)
        total += value // 10 + value % 10
    check = (10 - total % 10) % 10
    control = body[8]
    letter_controls = "JABCDEFGHI"
    if body[0] in "KLMNPQRSW":
        return control == letter_controls[check]
    if body[0] in "ABEH":
        return control == str(check)
    return control == str(check) or control == letter_controls[check]


def _pl(digits: str) -> bool:
    weights = (6, 5, 7, 2, 3, 4, 5, 6, 7)
    total = sum(int(digit) * weight for digit, weight in zip(digits[:9], weights))
    check = total % 11
    return check != 10 and check == int(digits[9])


def _luhn(digits: str) -> bool:
    total = 0
    reverse = digits[::-1]
    for index, char in enumerate(reverse):
        value = int(char)
        if index % 2 == 1:
            value *= 2
            if value > 9:
                value -= 9
        total += value
    return total % 10 == 0


def _se(digits: str) -> bool:
    org = digits[:10]
    return _luhn(org) and (len(digits) == 10 or digits[10:] == "01")


def _dk(digits: str) -> bool:
    weights = (2, 7, 6, 5, 4, 3, 2, 1)
    total = sum(int(digit) * weight for digit, weight in zip(digits, weights))
    return total % 11 == 0


def _fi(digits: str) -> bool:
    weights = (7, 9, 10, 5, 8, 4, 2)
    total = sum(int(digit) * weight for digit, weight in zip(digits[:7], weights))
    remainder = total % 11
    if remainder == 1:
        return False
    check = 0 if remainder == 0 else 11 - remainder
    return check == int(digits[7])


def _pt(digits: str) -> bool:
    weights = (9, 8, 7, 6, 5, 4, 3, 2)
    total = sum(int(digit) * weight for digit, weight in zip(digits[:8], weights))
    remainder = 11 - total % 11
    check = 0 if remainder >= 10 else remainder
    return check == int(digits[8])


def _lu(digits: str) -> bool:
    return int(digits[:6]) % 89 == int(digits[6:])


def _ie_shape(body: str) -> bool:
    if len(body) == 8 and body[0].isdigit() and body[7].isalpha() and body[1:7].isalnum():
        return True
    if len(body) == 9 and body[0].isdigit() and body[7].isalpha() and body[8].isalpha() and body[1:7].isdigit():
        return True
    return False


def _ie(body: str) -> bool:
    alphabet = "WABCDEFGHIJKLMNOPQRSTUV"
    if len(body) == 8:
        # Two 8-character shapes share this branch. The common one is 7
        # digits plus a check letter, weighed as-is. The older one (digit,
        # letter, 5 digits, check letter -- e.g. the legacy "8Z49289F"
        # shape) cannot be weighed as typed: Revenue's own check-digit
        # definition first rearranges it to "0" + the middle 5 digits + the
        # leading digit before applying the same mod-23 weights. The prior
        # version instead spliced a literal "7" in for the letter and left
        # the leading digit in place -- it never moved anything, so it was
        # computing a checksum for a number that was not the one on the
        # invoice. Every valid legacy-format Irish VAT number failed this
        # check, silently: it read as a typo the same way a correctly-typed
        # one would.
        source = body[:7] if body[1].isdigit() else "0" + body[2:7] + body[0]
        if not source.isdigit() or len(source) != 7:
            return False
        numeric = [int(char) for char in source]
        total = sum(value * weight for value, weight in zip(numeric, range(8, 1, -1)))
        return body[7] == alphabet[total % 23]
    if len(body) == 9 and body[:7].isdigit():
        numeric = [int(char) for char in body[:7]]
        extra = alphabet.index(body[8]) if body[8] in alphabet else -1
        if extra < 0:
            return False
        total = sum(value * weight for value, weight in zip(numeric, range(8, 1, -1))) + extra * 9
        return body[7] == alphabet[total % 23]
    return False


def _gb(digits: str) -> bool:
    weights = (8, 7, 6, 5, 4, 3, 2)
    total = sum(int(digit) * weight for digit, weight in zip(digits[:7], weights))
    check = int(digits[7:9])
    if len(digits) not in (9, 12):
        return False
    if len(digits) == 12 and digits[9:] != "000":
        return False
    return (total + check) % 97 == 0 or (total + 55 + check) % 97 == 0


def _finding(rule: str, message: str, fix: str, path: str) -> dict[str, str]:
    return {"rule": rule, "message": message, "fix": fix, "path": path}

